const AccountTypeSchema = z
  .enum(['prime', 'business', 'cdp'])
  .openapi({
    description:
      'The type of the Account.\n\n- `prime`: a linked Coinbase Prime account.\n- `business`: a linked Coinbase Business account.\n- `cdp`: a CDP-native account created via this API. Used for accounts created on\n  behalf of an Entity and for Customer-owned accounts.',
    example: 'prime',
  })
  .openapi('AccountType')

const OwnerSchema = z
  .string()
  .regex(/^(entity|customer)_[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$/)
  .openapi({
    description:
      'The Owner ID of the Account.\n\nOwner IDs are UUIDs prefixed with the Owner Type as follows:\n\n* **Entity**: `entity_` - If the Owner is your Entity, e.g. `entity_af2937b0-9846-4fe7-bfe9-ccc22d935114`.\n\n* **Customer**: `customer_` - If the Owner is one of your Customers,\n  e.g. `customer_af2937b0-9846-4fe7-bfe9-ccc22d935114`. Customer ownership requires the\n  Customer to have the `custodyCrypto`, `custodyFiat`, and `custodyStablecoin`\n  capabilities enabled.',
    example: 'entity_af2937b0-9846-4fe7-bfe9-ccc22d935114',
  })
  .openapi('Owner')

const AccountNameSchema = z
  .string()
  .regex(/^[a-zA-Z0-9 -]{1,64}$/)
  .max(64)
  .openapi({
    description:
      'An optional name for the account. Must be 1-64 characters and can only contain alphanumeric characters, hyphens, and spaces.',
    example: 'My Business Account',
  })
  .openapi('AccountName')

const AccountSchema = z
  .object({
    accountId: AccountIdSchema,
    type: AccountTypeSchema,
    owner: OwnerSchema,
    name: AccountNameSchema.exactOptional(),
    createdAt: z.iso
      .datetime({ offset: true })
      .openapi({
        description: 'The timestamp when the account was created.',
        example: '2023-10-08T14:30:00Z',
      }),
    updatedAt: z.iso
      .datetime({ offset: true })
      .openapi({
        description: 'The timestamp when the account was last updated.',
        example: '2023-10-08T14:30:00Z',
      }),
  })
  .openapi({ required: ['accountId', 'type', 'owner', 'createdAt', 'updatedAt'] })
  .openapi('Account')

const ListResponseSchema = z
