const TransferRequestSchema = z
  .object({
    source: CreateTransferSourceSchema,
    target: TransferTargetSchema,
    amount: PositiveDecimalSchema.openapi({
      description:
        'The amount of the transfer, as a decimal string in standard unit denomination of the asset specified by `asset` (e.g., "100.00" for 100 USD, "0.05" for 0.05 ETH).',
      example: '100.00',
    }),
    asset: AssetSchema.openapi({
      description:
        'The symbol of the asset for the amount. This must be one of the assets of the source or target.',
      example: 'usd',
    }),
    amountType: z
      .enum(['target', 'source'])
      .default('source')
      .exactOptional()
      .openapi({
        description:
          'Specifies whether the given amount is to be received by the target or taken from the source.\n\n- `target`: The transfer `target` receives the exact value specified in `amount`. Fees are added to the amount taken from the transfer `source`.\n- `source`: The transfer `target` receives the value specified in `amount`, minus any fees.\n',
        example: 'source',
      }),
    validateOnly: z
      .boolean()
      .default(false)
      .exactOptional()
      .openapi({
        description:
          'If true, validates the transfer without initiating it.  If the request is valid, a 2xx will be returned. If the request is invalid, a 4xx error will be returned. The response will include an errorType, for e.g. invalid_target if the specified target cannot receive funds.',
        example: false,
      }),
    execute: z
      .boolean()
      .openapi({
        description:
          'Whether to immediately execute the transfer. If false, the transfer will be created in quoted status and must be executed manually via the /execute endpoint.',
        example: true,
      }),
    metadata: MetadataSchema.exactOptional(),
    travelRule: TravelRuleSchema.exactOptional().openapi({
      description:
        'Travel Rule compliance information for this transfer. Required for transfers to external wallets above regulatory thresholds. Fields required differ by region and Coinbase contracting entity.',
      example: {
        isSelf: false,
        isIntermediary: false,
        originator: {
          name: 'John Doe',
          address: {
            line1: '123 Main St',
            city: 'San Francisco',
            state: 'CA',
            postCode: '94105',
            countryCode: 'US',
          },
        },
        beneficiary: { name: 'Jane Smith', walletType: 'custodial' },
      },
    }),
  })
  .openapi({
    description: 'A request to create a transfer.',
    required: ['source', 'target', 'amount', 'asset', 'execute'],
  })
  .openapi('TransferRequest')

