const WebhookEventResponseDetailSchema = z
  .object({
    httpCode: z
      .int()
      .exactOptional()
      .openapi({ description: 'HTTP status code returned by the webhook target.', example: 200 }),
    elapsedTimeMs: z
      .int()
      .exactOptional()
      .openapi({
        description: 'Round-trip time of the webhook delivery in milliseconds.',
        example: 142,
      }),
    body: z
      .string()
      .exactOptional()
      .openapi({ description: 'Response body returned by the webhook target.', example: 'ok' }),
    errorName: z
      .string()
      .exactOptional()
      .openapi({
        description: 'Error name if the delivery failed (e.g., timeout, connection_refused).',
        example: 'timeout',
      }),
  })
  .openapi({
    description: 'Details of the HTTP response received from the webhook target.',
    example: { httpCode: 200, elapsedTimeMs: 142, body: 'ok' },
    required: [],
  })
  .openapi('WebhookEventResponseDetail')

const WebhookEventResponseSchema = z
  .object({
    eventId: z
      .string()
      .openapi({
        description: 'Unique identifier for the webhook event.',
        example: 'a1b2c3d4-e5f6-7890-abcd-ef1234567890',
      }),
    eventTypeName: z
      .string()
      .openapi({
        description: 'The type of event that was delivered (e.g., "onchain.activity.detected").',
        example: 'onchain.activity.detected',
      }),
    status: z
      .enum(['pending', 'processing', 'succeeded', 'failed', 'retrying'])
      .openapi({ description: 'Current delivery status of the event.', example: 'succeeded' }),
    createdAt: z.iso
      .datetime({ offset: true })
      .openapi({
        description: 'Timestamp when the event delivery attempt was created.',
        example: '2025-01-15T10:30:00Z',
      }),
    succeededAt: z.iso
      .datetime({ offset: true })
      .exactOptional()
      .openapi({
        description:
          'Timestamp when the event was successfully delivered. Only present if status is "succeeded".',
        example: '2025-01-15T10:30:02Z',
      }),
    retryCount: z
      .int()
      .openapi({ description: 'Number of delivery retry attempts so far.', example: 0 }),
    response: WebhookEventResponseDetailSchema.exactOptional(),
  })
  .openapi({
    description: 'Details of a webhook event delivery attempt for a subscription.',
    required: ['eventId', 'eventTypeName', 'status', 'createdAt', 'retryCount'],
    example: {
      eventId: 'a1b2c3d4-e5f6-7890-abcd-ef1234567890',
      eventTypeName: 'onchain.activity.detected',
      status: 'succeeded',
      createdAt: '2025-01-15T10:30:00Z',
      succeededAt: '2025-01-15T10:30:02Z',
      retryCount: 0,
      response: { httpCode: 200, elapsedTimeMs: 142, body: 'ok' },
    },
  })
  .openapi('WebhookEventResponse')

const WebhookEventListResponseSchema = z
