const X402SettlePaymentRejectionSchema = z
  .object({
    success: z
      .boolean()
      .openapi({
        description: 'Indicates whether the payment settlement is successful.',
        example: false,
      }),
    errorReason: X402SettleErrorReasonSchema,
    errorMessage: z
      .string()
      .exactOptional()
      .openapi({
        description: 'The message describing the error reason.',
        example: 'Insufficient funds',
      }),
    payer: BlockchainAddressSchema.exactOptional().openapi({
      description:
        'The onchain address of the client that is paying for the resource.\n\nFor EVM networks, the payer will be a 0x-prefixed, checksum EVM address.\n\nFor Solana-based networks, the payer will be a base58-encoded Solana address.',
      example: '0x742d35Cc6634C0532925a3b844Bc454e4438f44e',
    }),
    transaction: z
      .string()
      .regex(/^(0x[a-fA-F0-9]{64}|[1-9A-HJ-NP-Za-km-z]{87,88})$/)
      .exactOptional()
      .openapi({
        description:
          'The transaction of the settlement.\nFor EVM networks, the transaction will be a 0x-prefixed, EVM transaction hash.\nFor Solana-based networks, the transaction will be a base58-encoded Solana signature.\nPopulated even though `success` is `false` when `errorReason` is `settlement_pending`: the transaction broadcast successfully but its receipt could not be retrieved, so the hash is returned for the caller to reconcile before retrying.',
        example: '0x89c91c789e57059b17285e7ba1716a1f5ff4c5dace0ea5a5135f26158d0421b9',
      }),
    network: z
      .string()
      .exactOptional()
      .openapi({ description: 'The network where the settlement occurred.', example: 'base' }),
  })
  .openapi({
    description: 'The result when x402 payment settlement fails.',
    required: ['success', 'errorReason'],
    example: {
      success: false,
      errorReason: 'insufficient_funds',
      payer: '0x742d35Cc6634C0532925a3b844Bc454e4438f44e',
    },
  })
  .openapi('X402SettlePaymentRejection')

const X402SupportedPaymentKindSchema = z
  .object({
    x402Version: X402VersionSchema,
    scheme: z
      .enum(['exact', 'upto', 'batch-settlement'])
      .openapi({ description: 'The scheme of the payment protocol.', example: 'exact' }),
    network: z
      .enum([
        'base-sepolia',
        'base',
        'solana-devnet',
        'solana',
        'eip155:8453',
        'eip155:84532',
        'eip155:137',
        'eip155:42161',
        'eip155:143',
        'eip155:480',
        'eip155:4801',
        'solana:5eykt4UsFv8P8NJdTREpY1vzqKqZKvdp',
        'solana:EtWTRABZaYq6iMfeYKouRu166VU2xqa1',
      ])
      .openapi({
        description:
          'The network of the blockchain. The format corresponds to the `x402Version` of the enclosing `x402SupportedPaymentKind`: v1 uses human-readable names (see `X402V1Network`); v2 uses CAIP-2 chain IDs (see `X402V2Network`).',
        example: 'base',
      }),
    extra: z
      .looseObject({})
      .exactOptional()
      .openapi({
        description:
          'The optional additional scheme-specific payment info.\nCommon scheme-specific fields:\n  - `exact` on Solana: `feePayer` — the base58-encoded Solana address that pays transaction fees.\n  - `upto` on EVM: `name`, `version`, and `facilitatorAddress` — the EVM address of the facilitator that the client must bind into the Permit2 witness when constructing the payment payload.\n  - `batch-settlement` on EVM: `name`, `version`, `receiverAuthorizer` (the EVM address authorized to sign claim batches), `withdrawDelay` (channel non-cooperative withdraw delay in seconds, 900–2,592,000), and optionally `assetTransferMethod` (e.g., `"eip3009"`).',
        example: { feePayer: 'HpabPRRCFbBKSuJr5PdkVvQc85FyxyTWkFM2obBRSvHT' },
      }),
  })
  .openapi({
    description:
      'The supported payment kind for the x402 protocol. A kind is comprised of a scheme and a network, which together uniquely identify a way to move money on the x402 protocol. For more details, please see [x402 Schemes](https://github.com/coinbase/x402?tab=readme-ov-file#schemes).',
    required: ['x402Version', 'scheme', 'network'],
  })
  .openapi('X402SupportedPaymentKind')

const X402ResourceQualitySchema = z
  .object({
    l30DaysTotalCalls: z
      .int()
      .exactOptional()
      .openapi({
        description: 'Total number of paid calls to a resource in the last 30 days.',
        example: 42,
      }),
    l30DaysUniquePayers: z
      .int()
      .exactOptional()
      .openapi({
        description: 'Number of unique payers to a resource in the last 30 days.',
        example: 15,
      }),
    lastCalledAt: z.iso
      .datetime({ offset: true })
      .exactOptional()
      .openapi({
        description: 'Timestamp of the most recent paid call to a resource.',
        example: '2024-01-15T10:30:00Z',
      }),
  })
  .openapi({
    description: 'Quality metrics for a discovered x402 resource.',
    example: {
      l30DaysTotalCalls: 42,
      l30DaysUniquePayers: 15,
      lastCalledAt: '2024-01-15T10:30:00Z',
    },
    required: [],
  })
  .openapi('X402ResourceQuality')

const X402DiscoveryResourceSchema = z
  .object({
    resource: z
      .string()
      .openapi({
        description: 'The URL of the resource.',
        example: 'https://api.example.com/weather/forecast',
      }),
    description: z
      .string()
      .exactOptional()
      .openapi({
        description: 'A human-readable description of the resource.',
        example: 'Real-time weather forecast data',
      }),
    type: z
      .enum(['http', 'mcp'])
      .openapi({ description: 'Communication protocol (e.g., "http", "mcp").', example: 'http' }),
    x402Version: X402VersionSchema,
    lastUpdated: z.iso
      .datetime({ offset: true })
      .exactOptional()
      .openapi({ description: 'Timestamp of the last update.', example: '2024-01-15T10:30:00Z' }),
    accepts: z
      .array(X402PaymentRequirementsSchema)
      .exactOptional()
      .openapi({
        description: 'Payment requirements accepted by the resource.',
        example: [
          {
            scheme: 'exact',
            network: 'eip155:8453',
            amount: '1000000',
            payTo: '0x742d35Cc6634C0532925a3b844Bc454e4438f44e',
            asset: '0x036CbD53842c5426634e7929541eC2318f3dCF7e',
            maxTimeoutSeconds: 60,
          },
        ],
      }),
    extensions: z
      .looseObject({})
      .exactOptional()
      .openapi({
        description:
          'Map of x402 protocol extensions supported by the resource, keyed by extension name.',
        example: { bazaar: { info: { input: { type: 'http', method: 'GET' } }, schema: {} } },
      }),
    quality: X402ResourceQualitySchema.exactOptional(),
    serviceName: z
      .string()
      .exactOptional()
      .openapi({
        description:
          'Display name of the service this resource belongs to. This is a free-form\nlabel for grouping and presentation only — it is not a stable identifier, and two resources\nsharing the same `serviceName` are not guaranteed to belong to the same logical service.\n',
        example: 'Weather API',
      }),
    tags: z
      .array(z.string())
      .exactOptional()
      .openapi({
        description:
          'Low-cardinality string labels associated with the resource for client-side\nfiltering and display. Values are free-form (no controlled vocabulary) and case-sensitive.\nOrder is not significant and duplicates are not expected.\n',
        example: ['weather', 'data'],
      }),
    bundleSlugs: z
      .array(
        z
          .string()
          .regex(/^[a-z0-9]+(?:-[a-z0-9]+)*$/)
          .max(64),
      )
      .max(50)
      .exactOptional()
      .openapi({
        description:
          'Slugs of the curated x402 bundles this resource belongs to. A bundle is an ordered, named grouping of curated resources covering a common agent workflow. Present only for Coinbase-curated resources (`curated: true`); omitted when the resource is not curated or is not a member of any bundle.',
        example: ['defi-trading'],
      }),
    iconUrl: UrlSchema.exactOptional().openapi({
      description:
        'URL of a square icon representing the service this resource belongs to. Distinct from a\nbrand logo: this is intended for compact, list-view rendering (favicon-style) and is\nnormalized to a square aspect ratio at ingestion. The image is moderated and re-hosted by\nCoinbase, so the URL is stable and safe to render directly in clients. Omitted when the\nprovider did not supply an icon, when the supplied icon failed moderation, or when image\nprocessing was unavailable at ingestion time.\n',
      example: 'https://res.cloudinary.com/bdb-prod/image/upload/...',
    }),
    curated: z
      .boolean()
      .exactOptional()
      .openapi({
        description:
          'Whether this resource is a Coinbase-curated endpoint. Curated endpoints have passed the\npartner-admission and verification bar and surface higher in search and listing results.\nOmitted (treated as `false`) when the resource is not curated.\n',
        example: true,
      }),
    skillUrl: UrlSchema.exactOptional().openapi({
      description:
        'URL of the SKILL.md document describing how to use this resource. Omitted when the resource\nhas no associated skill document.\n',
      example: 'https://skills.cdp.coinbase.com/weather-api/SKILL.md',
    }),
  })
  .openapi({
    description:
      "A single discovered x402 resource. Its fields come from three sources:\n\n- **x402 protocol** — negotiated from the resource's payment-required response: `resource`,\n  `type`, `x402Version`, `accepts`, `extensions`.\n- **Provider-supplied** — metadata published by the resource owner: `description`,\n  `serviceName`, `tags`.\n- **Coinbase-derived** — added during ingestion and curation: `iconUrl`, `quality`,\n  `lastUpdated`, and (for Coinbase-curated endpoints only) `curated`, `skillUrl` (a\n  Coinbase-authored SKILL.md), and `bundleSlugs`.\n",
    required: ['resource', 'type', 'x402Version'],
  })
  .openapi('X402DiscoveryResource')

