const OnrampSessionRequestSchema = z
  .object({
    purchaseCurrency: z
      .string()
      .openapi({
        description:
          "The ticker (e.g. `BTC`, `USDC`, `SOL`) or the Coinbase UUID (e.g. `d85dce9b-5b73-5c3c-8978-522ce1d1c1b4`) of the crypto asset to be purchased.\n\nUse the [Onramp Buy Options API](https://docs.cdp.coinbase.com/api-reference/rest-api/onramp-offramp/get-buy-options) to discover the supported purchase currencies for your user's location.",
        example: 'USDC',
      }),
    destinationNetwork: z
      .string()
      .openapi({
        description:
          "The name of the crypto network the purchased currency will be sent on.\n\nUse the [Onramp Buy Options API](https://docs.cdp.coinbase.com/api-reference/rest-api/onramp-offramp/get-buy-options) to discover the supported networks for your user's location.",
        example: 'base',
      }),
    destinationAddress: BlockchainAddressSchema.openapi({
      description: 'The address the purchased crypto will be sent to.',
      example: '0x1234567890abcdef1234567890abcdef12345678',
    }),
    paymentAmount: z
      .string()
      .exactOptional()
      .openapi({
        description:
          'A string representing the amount of fiat the user wishes to pay in exchange for crypto. When using this parameter, the returned quote will be inclusive of fees i.e. the user will pay this exact amount of the payment currency.',
        example: '100.00',
      }),
    purchaseAmount: z
      .string()
      .exactOptional()
      .openapi({
        description:
          'A string representing the amount of crypto the user wishes to purchase. When using this parameter, the returned quote will be exclusive of fees i.e. the user will receive this exact amount of the purchase currency.',
        example: '10.000000',
      }),
    paymentCurrency: z
      .string()
      .exactOptional()
      .openapi({ description: 'The fiat currency to be converted to crypto.', example: 'USD' }),
    paymentMethod: OnrampQuotePaymentMethodTypeIdSchema.exactOptional(),
    country: z
      .string()
      .exactOptional()
      .openapi({ description: 'The ISO 3166-1 two letter country code (e.g. US).', example: 'US' }),
    subdivision: z
      .string()
      .exactOptional()
      .openapi({
        description: 'The ISO 3166-2 two letter state code (e.g. NY). Only required for US.',
        example: 'NY',
      }),
    redirectUrl: UriSchema.exactOptional().openapi({
      description:
        'URI to redirect the user to after they complete or dismiss the transaction. Embedded in the returned onramp URL as a query parameter.',
      example: 'https://example.com/success',
    }),
    clientIp: z
      .string()
      .exactOptional()
      .openapi({
        description: 'The IP address of the end user requesting the onramp transaction.',
        example: '127.0.0.1',
      }),
    partnerUserRef: z
      .string()
      .exactOptional()
      .openapi({
        description:
          'A unique string that represents the user in your app. This can be used to link individual transactions together so you can retrieve the transaction history for your users. Prefix this string with "sandbox-" (e.g. "sandbox-user-1234") to perform a sandbox transaction which will allow you to test your integration without any real transfer of funds.\n\nThis value can be used with the [Onramp User Transactions API](https://docs.cdp.coinbase.com/api-reference/rest-api/onramp-offramp/get-onramp-transactions-by-id) to retrieve all transactions created by the user.',
        example: 'user-1234',
      }),
  })
  .openapi({
    description:
      'Common request parameters shared by [Create Onramp Session](#operation/createOnrampSession) and [Create Onramp Mobile Challenge](#operation/createOnrampMobileChallenge).',
    required: ['destinationAddress', 'purchaseCurrency', 'destinationNetwork'],
  })
  .openapi('OnrampSessionRequest')

const OnrampSessionSchema = z
