const WalletHashSignedEventSchema = z
  .xor([
    WalletEvmSigningPayloadSchema.and(WalletApiKeyEventPayloadSchema).openapi({
      title: 'API Key Wallet (EVM)',
    }),
    WalletSolanaSigningPayloadSchema.and(WalletApiKeyEventPayloadSchema).openapi({
      title: 'API Key Wallet (Solana)',
    }),
    WalletEvmSigningPayloadSchema.and(WalletUserEventPayloadSchema).openapi({
      title: 'User Wallet (EVM)',
    }),
    WalletSolanaSigningPayloadSchema.and(WalletUserEventPayloadSchema).openapi({
      title: 'User Wallet (Solana)',
    }),
    WalletEvmSigningPayloadSchema.and(WalletDelegatedEventPayloadSchema).openapi({
      title: 'User Wallet (Delegated Signing, EVM)',
    }),
    WalletSolanaSigningPayloadSchema.and(WalletDelegatedEventPayloadSchema).openapi({
      title: 'User Wallet (Delegated Signing, Solana)',
    }),
  ])
  .openapi({
    'x-event-type': 'wallet.hash.signed',
    description:
      'Delivered when a raw hash is signed. Emitted for both EVM and Solana wallets. The payload is one of six variants: API Key Wallet, User Wallet, or User Wallet (Delegated Signing), each delivered as an EVM or Solana variant.',
  })
  .openapi('WalletHashSignedEvent')

const PaymentsTransfersEventBaseSchema = z
  .object({
    eventID: z
      .uuid()
      .openapi({
        description: 'Unique identifier for this webhook event. Use this for idempotency.',
        example: '123e4567-e89b-12d3-a456-426614174000',
      }),
    eventType: z
      .string()
      .openapi({
        description: 'The type of webhook event.',
        example: 'payments.transfers.completed',
      }),
    timestamp: z.iso
      .datetime({ offset: true })
      .openapi({
        description:
          'The UTC ISO 8601 timestamp at which the underlying state change occurred, not the time at which this webhook was delivered.',
        example: '2026-01-01T00:05:00Z',
      }),
    data: TransferSchema,
  })
  .openapi({
    description:
      'Common envelope fields included in every payments transfers webhook event payload.',
    required: ['eventID', 'eventType', 'timestamp', 'data'],
  })
  .openapi('PaymentsTransfersEventBase')

