const MoneyAmountSchema = z
  .object({
    currency: z
      .string()
      .openapi({ description: 'Currency code (e.g., "USD", "USDC", "ETH").', example: 'USD' }),
    value: z.string().openapi({ description: 'The amount as a string.', example: '100.00' }),
  })
  .openapi({
    description: 'A monetary amount with currency.',
    required: ['currency', 'value'],
    example: { currency: 'USD', value: '5.00' },
  })
  .openapi('MoneyAmount')

const OnrampTransactionPayloadSchema = z
  .object({
    eventType: z
      .string()
      .openapi({ description: 'The webhook event type.', example: 'onramp.transaction.updated' }),
    transactionId: z
      .string()
      .openapi({
        description: 'Unique transaction identifier.',
        example: '1f087a54-ff1f-62e8-9f85-aa77ac0499a5',
      }),
    status: z
      .enum([
        'ONRAMP_TRANSACTION_STATUS_UNSPECIFIED',
        'ONRAMP_TRANSACTION_STATUS_CREATED',
        'ONRAMP_TRANSACTION_STATUS_IN_PROGRESS',
        'ONRAMP_TRANSACTION_STATUS_SUCCESS',
        'ONRAMP_TRANSACTION_STATUS_FAILED',
        'ONRAMP_TRANSACTION_STATUS_AWAITING_AUTH',
        'ONRAMP_TRANSACTION_STATUS_AWAITING_PAYMENT',
      ])
      .openapi({
        description: 'Current status of the transaction.',
        example: 'ONRAMP_TRANSACTION_STATUS_IN_PROGRESS',
      }),
    purchaseCurrency: z
      .string()
      .exactOptional()
      .openapi({
        description: 'The crypto currency purchased (e.g., "USDC", "ETH").',
        example: 'USDC',
      }),
    purchaseNetwork: z
      .string()
      .exactOptional()
      .openapi({
        description: 'The blockchain network for the purchase (e.g., "ethereum", "base").',
        example: 'ethereum',
      }),
    purchaseAmount: MoneyAmountSchema.exactOptional(),
    paymentTotal: MoneyAmountSchema.exactOptional(),
    paymentTotalUsd: MoneyAmountSchema.exactOptional(),
    paymentSubtotal: MoneyAmountSchema.exactOptional(),
    coinbaseFee: MoneyAmountSchema.exactOptional(),
    networkFee: MoneyAmountSchema.exactOptional(),
    exchangeRate: MoneyAmountSchema.exactOptional(),
    txHash: z
      .string()
      .exactOptional()
      .openapi({
        description: 'The onchain transaction hash of the send (0x-prefixed for EVM).',
        example: '0x',
      }),
    createdAt: z.iso
      .datetime({ offset: true })
      .exactOptional()
      .openapi({
        description: 'When the transaction was created.',
        example: '2025-09-02T02:34:13Z',
      }),
    completedAt: z.iso
      .datetime({ offset: true })
      .exactOptional()
      .openapi({
        description: 'When the transaction completed (uses send_started_at for early success).',
        example: '0001-01-01T00:00:00Z',
      }),
    country: z
      .string()
      .exactOptional()
      .openapi({ description: "The user's country code.", example: 'US' }),
    userId: z
      .string()
      .exactOptional()
      .openapi({
        description: 'Hashed user identifier (entity hash for guest, user ID for authed).',
        example: '4132b63ee21128686458155b28570289',
      }),
    paymentMethod: z
      .enum([
        'UNSPECIFIED',
        'CARD',
        'ACH_BANK_ACCOUNT',
        'APPLE_PAY',
        'FIAT_WALLET',
        'CRYPTO_ACCOUNT',
        'GUEST_CHECKOUT_CARD',
        'PAYPAL',
        'RTP',
        'GUEST_CHECKOUT_APPLE_PAY',
        'GUEST_CHECKOUT_GOOGLE_PAY',
      ])
      .exactOptional()
      .openapi({ description: 'The payment method used.', example: 'CARD' }),
    walletAddress: z
      .string()
      .exactOptional()
      .openapi({
        description: 'The destination wallet address.',
        example: '0xe0512E358C347cc2b1A42d057065CE642068b7Ba',
      }),
    type: z
      .enum([
        'ONRAMP_TRANSACTION_TYPE_UNSPECIFIED',
        'ONRAMP_TRANSACTION_TYPE_BUY_AND_SEND',
        'ONRAMP_TRANSACTION_TYPE_SEND',
      ])
      .exactOptional()
      .openapi({
        description: 'The type of onramp transaction.',
        example: 'ONRAMP_TRANSACTION_TYPE_BUY_AND_SEND',
      }),
    userType: z
      .enum(['USER_TYPE_UNSPECIFIED', 'USER_TYPE_AUTHED', 'USER_TYPE_GUEST'])
      .exactOptional()
      .openapi({ description: 'Whether the user is authed or guest.', example: 'USER_TYPE_GUEST' }),
    partnerUserRef: z
      .string()
      .exactOptional()
      .openapi({
        description: 'The partnerUserId provided when initializing the onramp session.',
        example: 'example_user_ref',
      }),
    contractAddress: z
      .string()
      .exactOptional()
      .openapi({
        description: 'The token contract address (populated when asset metadata is available).',
        example: '',
      }),
    failureReason: z
      .enum([
        'FAILURE_REASON_UNSPECIFIED',
        'FAILURE_REASON_BUY_FAILED',
        'FAILURE_REASON_SEND_FAILED',
      ])
      .exactOptional()
      .openapi({
        description: 'The reason for failure (if applicable).',
        example: 'FAILURE_REASON_UNSPECIFIED',
      }),
    endPartnerName: z
      .string()
      .exactOptional()
      .openapi({ description: 'The name of the developer app.', example: '' }),
    errorCode: z
      .string()
      .exactOptional()
      .openapi({
        description: 'Error code for the transaction failure (if applicable).',
        example: 'ERROR_CODE_UNSPECIFIED',
      }),
    partnerId: z
      .string()
      .exactOptional()
      .openapi({
        description:
          'The Onramp-issued identifier of the end partner this transaction was scoped to via the X-Onramp-Partner-Id header on the session that initiated it. Only present for transactions created by an aggregator on behalf of a registered end partner.',
        example: '1f1c19e8-d0e9-6443-b706-92a4d033d043',
      }),
  })
  .openapi({
    description:
      'Webhook payload for standard onramp transactions (guest checkout and authed flow). Serialized from the OnrampTransaction proto via protojson with eventType appended.',
    required: ['eventType', 'transactionId', 'status'],
  })
  .openapi('OnrampTransactionPayload')

const OrderFeeSchema = z
  .object({
    feeType: z
      .enum(['FEE_TYPE_UNSPECIFIED', 'FEE_TYPE_NETWORK', 'FEE_TYPE_EXCHANGE'])
      .exactOptional()
      .openapi({ description: 'The type of fee.', example: 'FEE_TYPE_NETWORK' }),
    feeAmount: z
      .string()
      .exactOptional()
      .openapi({ description: 'The amount of the fee.', example: '0.5' }),
    feeCurrency: z
      .string()
      .exactOptional()
      .openapi({ description: 'The currency of the fee.', example: 'USD' }),
  })
  .openapi({ description: 'A fee associated with a Headless Onramp API order.', required: [] })
  .openapi('OrderFee')

const OnrampOrderPayloadSchema = z
  .object({
    eventType: z
      .string()
      .openapi({ description: 'The webhook event type.', example: 'onramp.transaction.success' }),
    orderId: z
      .uuid()
      .openapi({
        description: 'Unique order identifier.',
        example: '123e4567-e89b-12d3-a456-426614174000',
      }),
    paymentTotal: z
      .string()
      .exactOptional()
      .openapi({ description: 'The total fiat amount paid.', example: '100.75' }),
    paymentSubtotal: z
      .string()
      .exactOptional()
      .openapi({
        description: 'The fiat amount converted to crypto (excluding fees).',
        example: '100',
      }),
    paymentCurrency: z
      .string()
      .exactOptional()
      .openapi({ description: 'The fiat currency used for payment.', example: 'USD' }),
    paymentMethod: z
      .enum([
        'UNSPECIFIED',
        'CARD',
        'ACH_BANK_ACCOUNT',
        'APPLE_PAY',
        'FIAT_WALLET',
        'CRYPTO_ACCOUNT',
        'GUEST_CHECKOUT_CARD',
        'PAYPAL',
        'RTP',
        'GUEST_CHECKOUT_APPLE_PAY',
        'GUEST_CHECKOUT_GOOGLE_PAY',
      ])
      .exactOptional()
      .openapi({ description: 'The payment method used.', example: 'GUEST_CHECKOUT_APPLE_PAY' }),
    purchaseAmount: z
      .string()
      .exactOptional()
      .openapi({ description: 'The amount of crypto purchased.', example: '100.000000' }),
    purchaseCurrency: z
      .string()
      .exactOptional()
      .openapi({ description: 'The crypto currency purchased.', example: 'USDC' }),
    fees: z
      .array(OrderFeeSchema)
      .exactOptional()
      .openapi({
        description: 'Breakdown of fees for the order.',
        example: [
          { feeType: 'FEE_TYPE_NETWORK', feeAmount: '0.5', feeCurrency: 'USD' },
          { feeType: 'FEE_TYPE_EXCHANGE', feeAmount: '0.25', feeCurrency: 'USD' },
        ],
      }),
    exchangeRate: z
      .string()
      .exactOptional()
      .openapi({ description: 'The exchange rate used for conversion.', example: '1' }),
    destinationAddress: z
      .string()
      .exactOptional()
      .openapi({
        description: 'The destination wallet address.',
        example: '0x1234567890abcdef1234567890abcdef12345678',
      }),
    destinationNetwork: z
      .string()
      .exactOptional()
      .openapi({ description: 'The blockchain network for delivery.', example: 'base' }),
    status: z
      .enum([
        'ONRAMP_ORDER_STATUS_UNSPECIFIED',
        'ONRAMP_ORDER_STATUS_PENDING_AUTH',
        'ONRAMP_ORDER_STATUS_PENDING_VERIFICATION',
        'ONRAMP_ORDER_STATUS_PENDING_PAYMENT',
        'ONRAMP_ORDER_STATUS_PROCESSING',
        'ONRAMP_ORDER_STATUS_COMPLETED',
        'ONRAMP_ORDER_STATUS_FAILED',
      ])
      .openapi({
        description: 'The status of the order.',
        example: 'ONRAMP_ORDER_STATUS_COMPLETED',
      }),
    txHash: z
      .string()
      .exactOptional()
      .openapi({
        description: 'The onchain transaction hash (available once crypto is sent).',
        example: '0xabcdef1234567890abcdef1234567890abcdef1234567890abcdef1234567890',
      }),
    createdAt: z.iso
      .datetime({ offset: true })
      .exactOptional()
      .openapi({ description: 'When the order was created.', example: '2025-09-10T10:30:00Z' }),
    updatedAt: z.iso
      .datetime({ offset: true })
      .exactOptional()
      .openapi({
        description: 'When the order was last updated.',
        example: '2025-09-10T10:35:00Z',
      }),
    partnerUserRef: z
      .string()
      .exactOptional()
      .openapi({ description: 'The partner user reference ID.', example: 'example_user_ref' }),
    partnerId: z
      .string()
      .exactOptional()
      .openapi({
        description:
          'The Onramp-issued identifier of the end partner this order was scoped to via the X-Onramp-Partner-Id header. Only present for orders created by an aggregator on behalf of a registered end partner.',
        example: '1f1c19e8-d0e9-6443-b706-92a4d033d043',
      }),
  })
  .openapi({
    description:
      'Webhook payload for Headless Onramp API orders (Apple Pay / Google Pay). Serialized from the OnrampOrder proto via protojson with eventType appended.',
    required: ['eventType', 'orderId', 'status'],
  })
  .openapi('OnrampOrderPayload')

const OnrampTransactionEventSchema = z
  .xor([OnrampTransactionPayloadSchema, OnrampOrderPayloadSchema])
  .openapi({
    description:
      'Webhook payload for all onramp transaction events (created, updated, success, failed). Shape depends on transaction type — standard flow (guest checkout / authorized) uses OnrampTransactionPayload, Headless API (Apple Pay / Google Pay) uses OnrampOrderPayload. Distinguish by presence of `orderId` (Headless) vs `transactionId` (standard).',
  })
  .openapi('OnrampTransactionEvent')

