const PageSizeParamsSchema = z
  .preprocess(
    (val) =>
      typeof val === 'string' &&
      /^-?(\d+(\.\d*)?|\.\d+)([eE][+-]?\d+)?$/.test(val) &&
      (!/^-?\d+$/.test(val) || Number.isSafeInteger(Number(val)))
        ? Number(val)
        : val,
    z.int(),
  )
  .default(20)
  .exactOptional()
  .openapi({
    param: {
      name: 'pageSize',
      description: 'The number of resources to return per page.',
      in: 'query',
      required: false,
      schema: { type: 'integer', default: 20 },
      example: 10,
    },
  })

const PageTokenParamsSchema = z
  .string()
  .exactOptional()
  .openapi({
    param: {
      name: 'pageToken',
      description: 'The token for the next page of resources, if any.',
      in: 'query',
      required: false,
      schema: { type: 'string' },
      example: 'eyJsYXN0X2lkIjogImFiYzEyMyIsICJ0aW1lc3RhbXAiOiAxNzA3ODIzNzAxfQ==',
    },
  })

const IdempotencyKeyParamsSchema = z
  .string()
  .min(1)
  .max(128)
  .exactOptional()
  .openapi({
    param: {
      name: 'X-Idempotency-Key',
      in: 'header',
      required: false,
      description:
        'An optional string request header for making requests safely retryable.\nWhen included, duplicate requests with the same key will return identical responses.\nRefer to our [Idempotency docs](https://docs.cdp.coinbase.com/api-reference/v2/idempotency) for more information on using idempotency keys.\n',
      schema: { type: 'string', maxLength: 128, minLength: 1 },
      example: '8e03978e-40d5-43e8-bc93-6894a57f9324',
    },
  })

const XWalletAuthParamsSchema = z
