export const postV2AccountsRoute = createRoute({
  method: 'post',
  path: '/v2/accounts',
  tags: ['Accounts'],
  summary: 'Create account',
  description:
    "Create an account. Two ownership modes are supported:\n\n- **Entity-owned**: when `owner` is omitted, the account is owned by the\n  Entity making the request. Returns an account with `owner: entity_<uuid>`.\n  Omit `compliance`; it has no effect for Entity-owned accounts.\n\n- **Customer-owned**: pass a Customer ID as `owner`\n  (e.g. `customer_af2937b0-9846-4fe7-bfe9-ccc22d935114`). The Customer\n  must have the `custodyCrypto`, `custodyFiat`, and `custodyStablecoin`\n  capabilities enabled, otherwise the request is rejected with\n  `customer_not_authorized` (HTTP 403). `compliance.requesterIpAddress`\n  is required; use the IP address of the end-customer who initiated the\n  request (not the partner server's IP).",
  operationId: 'createFoundationAccount',
  request: {
    headers: z.object({ 'X-Idempotency-Key': IdempotencyKeyParamsSchema }),
    body: {
      content: {
        'application/json': {
          schema: CreateAccountRequestSchema,
          examples: {
            entity_owned: {
              summary: 'Create an account owned by your Entity',
              value: { name: 'My Business Account' },
            },
            customer_owned: {
              summary: 'Create an account owned by a Customer of yours',
              value: {
                owner: 'customer_af2937b0-9846-4fe7-bfe9-ccc22d935114',
                name: 'ABC XYZ Customer Account',
                compliance: { requesterIpAddress: '203.0.113.42' },
              },
            },
          },
        },
      },
      required: true,
    },
  },
  responses: {
    200: {
      description: 'Successfully created account.',
      content: {
        'application/json': {
          schema: AccountSchema,
          examples: {
            entity_owned: {
              summary: 'Account owned by your Entity',
              value: {
                accountId: 'account_af2937b0-9846-4fe7-bfe9-ccc22d935114',
                type: 'cdp',
                owner: 'entity_af2937b0-9846-4fe7-bfe9-ccc22d935114',
                name: 'My Business Account',
                createdAt: '2023-10-08T14:30:00Z',
                updatedAt: '2023-10-08T14:30:00Z',
              },
            },
            customer_owned: {
              summary: 'Account owned by a Customer of yours',
              value: {
                accountId: 'account_af2937b0-9846-4fe7-bfe9-ccc22d935114',
                type: 'cdp',
                owner: 'customer_af2937b0-9846-4fe7-bfe9-ccc22d935114',
                name: 'ABC XYZ Customer Account',
                createdAt: '2023-10-08T14:30:00Z',
                updatedAt: '2023-10-08T14:30:00Z',
              },
            },
          },
        },
      },
    },
    400: {
      description: 'Invalid request.',
      content: {
        'application/json': {
          schema: ErrorSchema,
          examples: {
            invalid_request: {
              value: {
                errorType: 'invalid_request',
                errorMessage: 'Invalid account creation request.',
              },
            },
          },
        },
      },
    },
    403: {
      description:
        'Customer is not authorized for one or more capabilities required by this action.',
      content: {
        'application/json': {
          schema: ErrorSchema,
          examples: {
            customer_not_authorized: {
              summary: 'Customer is not authorized for one or more required capabilities',
              value: {
                errorType: 'customer_not_authorized',
                errorMessage:
                  'Customer is not authorized for one or more capabilities required by this action.',
                unauthorizedCapabilities: ['custodyCrypto', 'custodyFiat', 'custodyStablecoin'],
              },
            },
          },
        },
      },
    },
    422: IdempotencyErrorResponse,
    503: EndpointUnavailableErrorResponse,
  },
  security: [{ apiKeyAuth: [] }],
})

