export const getV2CustomersRequirementsRoute = createRoute({
  method: 'get',
  path: '/v2/customers/requirements',
  tags: ['Customers'],
  summary: 'Get customer requirements',
  description:
    "Preview the requirements a hypothetical customer of the given\n`customerType` and jurisdiction would need to satisfy to enable the\nrequested `capabilities`, without creating a customer record.\nPartner onboarding UIs can use this to render the collection flow\nbefore any customer state exists.\n\nToday this endpoint only previews the Terms of Service requirement:\nthe response's `RequirementsMap` will only ever contain a `tos` key.\nOther requirement families (PII / CDD inputs) are not yet available\nthrough this endpoint; use `POST /v2/customers` or\n`PUT /v2/customers/{customerId}` to discover those via\n`Customer.requirements`.\n\nOnly `customerType: individual` customers resident in or citizens\nof the US are currently supported; every other combination returns\n`400 invalid_request`.\n",
  operationId: 'getCustomerRequirements',
  request: {
    query: z.object({
      customerType: CustomerTypeSchema.openapi({
        param: {
          name: 'customerType',
          in: 'query',
          required: true,
          description: 'The type of the hypothetical customer.',
          schema: { $ref: '#/components/schemas/CustomerType' },
          example: 'individual',
        },
      }),
      capabilities: z
        .preprocess(
          (val) => (val === undefined || Array.isArray(val) ? val : [val]),
          z.array(CapabilityNameSchema).min(1),
        )
        .openapi({
          param: {
            name: 'capabilities',
            in: 'query',
            required: true,
            description:
              'The capabilities the hypothetical customer would request.\nRepeat the parameter to specify multiple capabilities, for\nexample `capabilities=custodyCrypto&capabilities=transferCrypto`.\n',
            style: 'form',
            explode: true,
            schema: {
              type: 'array',
              minItems: 1,
              items: { $ref: '#/components/schemas/CapabilityName' },
            },
            example: ['custodyCrypto', 'transferCrypto'],
          },
        }),
      countryCode: CountryCodeSchema.openapi({
        param: {
          name: 'countryCode',
          in: 'query',
          required: false,
          description:
            "The hypothetical customer's country of residence. At least one\nof `countryCode` or `citizenship` is required. When both are\npresent, `countryCode` takes precedence.\n",
          schema: { $ref: '#/components/schemas/CountryCode' },
          example: 'US',
        },
      }).exactOptional(),
      citizenship: CountryCodeSchema.openapi({
        param: {
          name: 'citizenship',
          in: 'query',
          required: false,
          description:
            "The hypothetical customer's citizenship. At least one of\n`countryCode` or `citizenship` is required.\n",
          schema: { $ref: '#/components/schemas/CountryCode' },
          example: 'US',
        },
      }).exactOptional(),
    }),
  },
  responses: {
    200: {
      description: 'Successfully previewed requirements.',
      content: {
        'application/json': {
          schema: RequirementsMapSchema,
          example: {
            tos: {
              status: 'due',
              impact: ['custodyCrypto', 'transferCrypto'],
              tosVersions: [
                {
                  versionId: 'us_individual_2026-05-29',
                  languages: ['en'],
                  url: 'https://www.coinbase.com/legal/user-agreements-third-party-provider',
                },
              ],
            },
          },
        },
      },
    },
    400: {
      description:
        'Invalid request. Distinct causes include a missing required\nparameter, both `countryCode` and `citizenship` omitted, an\nunrecognized `capabilities` value, and a\n`(customerType, jurisdiction)` combination that is not yet\nsupported (currently only `individual` customers resident in or\ncitizens of the US).',
      content: {
        'application/json': {
          schema: ErrorSchema,
          examples: {
            invalid_request: {
              summary: 'Generic invalid request',
              value: {
                errorType: 'invalid_request',
                errorMessage: 'Invalid request. Please check the request parameters.',
              },
            },
            missing_required_parameter: {
              summary: 'Missing required `customerType`',
              value: {
                errorType: 'invalid_request',
                errorMessage: "Query parameter 'customerType' is required.",
              },
            },
            unrecognized_capability: {
              summary: 'Unrecognized `capabilities` value',
              value: {
                errorType: 'invalid_request',
                errorMessage: "Unknown capability 'notACapability'.",
              },
            },
            missing_jurisdiction: {
              summary: 'Neither `countryCode` nor `citizenship` provided',
              value: {
                errorType: 'invalid_request',
                errorMessage: "At least one of 'countryCode' or 'citizenship' is required.",
              },
            },
            unsupported_combination: {
              summary: '`(customerType, jurisdiction)` combination is not yet supported',
              value: {
                errorType: 'invalid_request',
                errorMessage:
                  "Requirements are not yet supported for customerType 'business' outside the US.",
              },
            },
          },
        },
      },
    },
    401: UnauthorizedErrorResponse,
    500: InternalServerErrorResponse,
    502: BadGatewayErrorResponse,
    503: ServiceUnavailableErrorResponse,
  },
  security: [{ apiKeyAuth: [] }],
})

