export const getV2TransfersRoute = createRoute({
  method: 'get',
  path: '/v2/transfers',
  tags: ['Transfers'],
  summary: 'List transfers',
  description:
    'List transfers for your organization. Use this to view and monitor your transfer activity.\n\n**Sorting**: Results are sorted by creation time in descending order (newest first). Transfers with the same creation time are returned in a consistent order across pages.\n\n**Status Filtering**: Filter by specific status to efficiently manage transfers:\n* `?status=processing` - Monitor active transfers.\n* `?status=quoted` - Find transfers awaiting execution.\n* `?status=failed` - Review failed transfers for troubleshooting.\n* `?status=completed` - Find completed transfers.\n\n**Account Filtering**: Filter by account ID to find transfers involving a specific account:\n* `?accountId=<ID>` - All transfers where the account is either source or target (OR semantics).\n* `?sourceAccountId=<ID>` - Only transfers where the account is the source (outbound).\n* `?targetAccountId=<ID>` - Only transfers where the account is the target (inbound).\nProviding `accountId` together with `sourceAccountId`, `targetAccountId`, `sourceAddress`, `targetAddress`, or `targetEmail` is a validation error and returns HTTP 400.\n\n**Date Range Filtering**: Filter by creation or last-updated time for reconciliation:\n* `?createdAfter=2026-01-01T00:00:00Z&createdBefore=2026-01-31T23:59:59Z` - Transfers created within a date range.\n* `?updatedAfter=2026-01-01T00:00:00Z` - Transfers updated since a given time. Useful for incremental sync.\n\n**Asset Filtering**: Filter by source or target asset symbol:\n* `?sourceAsset=usd` - Transfers funded from a USD account.\n* `?targetAsset=usdc` - Transfers delivering USDC to the target.\nSupported asset symbols include `usdc`, `eurc`, `usd`, and `eur`.\n\n**Other Filters**:\n* `?sourceAddress=0x...` - Transfers from a specific on-chain source address.\n* `?targetAddress=0x...` - Transfers to a specific on-chain destination address.\n* `?targetEmail=user@example.com` - Transfers to a specific email recipient.\n* `?transferId=transfer_...` - Look up a single transfer by ID; bypasses pagination.\n\n**Filter Combinations**: The following combinations are validation errors and return HTTP 400:\n* `accountId` with any of `sourceAccountId`, `targetAccountId`, `sourceAddress`, `targetAddress`, or `targetEmail`.\n* `sourceAccountId` with `sourceAddress`.\n* More than one of `targetAccountId`, `targetAddress`, and `targetEmail`.\n* `transferId` with any other filter. Pagination parameters are permitted.',
  operationId: 'listTransfers',
  request: {
    query: z.object({
      status: TransferStatusSchema.openapi({
        param: {
          name: 'status',
          in: 'query',
          required: false,
          description:
            'Filter transfers by status. Useful for building dashboards, monitoring active transfers, or finding transfers needing action.',
          example: 'quoted',
          schema: { $ref: '#/components/schemas/TransferStatus' },
        },
      }).exactOptional(),
      accountId: AccountIdSchema.openapi({
        param: {
          name: 'accountId',
          in: 'query',
          required: false,
          description:
            'Filter transfers by account ID. Returns transfers where the specified account is either the source or target (OR semantics). Cannot be combined with `sourceAccountId`, `targetAccountId`, `sourceAddress`, `targetAddress`, or `targetEmail`.',
          schema: { $ref: '#/components/schemas/AccountId' },
          example: 'account_af2937b0-9846-4fe7-bfe9-ccc22d935114',
        },
      }).exactOptional(),
      sourceAccountId: AccountIdSchema.openapi({
        param: {
          name: 'sourceAccountId',
          in: 'query',
          required: false,
          description:
            'Filter transfers by source account ID. Returns only transfers where the specified account is the source. Cannot be combined with `accountId` or `sourceAddress`.',
          schema: { $ref: '#/components/schemas/AccountId' },
          example: 'account_af2937b0-9846-4fe7-bfe9-ccc22d935114',
        },
      }).exactOptional(),
      targetAccountId: AccountIdSchema.openapi({
        param: {
          name: 'targetAccountId',
          in: 'query',
          required: false,
          description:
            'Filter transfers by target account ID. Returns only transfers where the specified account is the target. Cannot be combined with `accountId`, `targetAddress`, or `targetEmail`.',
          schema: { $ref: '#/components/schemas/AccountId' },
          example: 'account_af2937b0-9846-4fe7-bfe9-ccc22d935114',
        },
      }).exactOptional(),
      createdAfter: z.iso
        .datetime({ offset: true })
        .exactOptional()
        .openapi({
          param: {
            name: 'createdAfter',
            in: 'query',
            required: false,
            description:
              'Filter transfers to those created at or after this datetime (inclusive). ISO 8601 format.',
            example: '2026-01-01T00:00:00Z',
            schema: { type: 'string', format: 'date-time' },
          },
        }),
      createdBefore: z.iso
        .datetime({ offset: true })
        .exactOptional()
        .openapi({
          param: {
            name: 'createdBefore',
            in: 'query',
            required: false,
            description:
              'Filter transfers to those created at or before this datetime (inclusive). ISO 8601 format.',
            example: '2026-01-31T23:59:59Z',
            schema: { type: 'string', format: 'date-time' },
          },
        }),
      updatedAfter: z.iso
        .datetime({ offset: true })
        .exactOptional()
        .openapi({
          param: {
            name: 'updatedAfter',
            in: 'query',
            required: false,
            description:
              'Filter transfers to those updated at or after this datetime (inclusive). ISO 8601 format. Useful for incremental sync — poll for transfers that changed state since your last check.',
            example: '2026-01-01T00:00:00Z',
            schema: { type: 'string', format: 'date-time' },
          },
        }),
      updatedBefore: z.iso
        .datetime({ offset: true })
        .exactOptional()
        .openapi({
          param: {
            name: 'updatedBefore',
            in: 'query',
            required: false,
            description:
              'Filter transfers to those updated at or before this datetime (inclusive). ISO 8601 format.',
            example: '2026-01-31T23:59:59Z',
            schema: { type: 'string', format: 'date-time' },
          },
        }),
      sourceAsset: z
        .string()
        .exactOptional()
        .openapi({
          param: {
            name: 'sourceAsset',
            in: 'query',
            required: false,
            description:
              'Filter transfers by source asset symbol (e.g., `usd`, `usdc`, `eurc`, `eur`).',
            example: 'usd',
            schema: { type: 'string' },
          },
        }),
      targetAsset: z
        .string()
        .exactOptional()
        .openapi({
          param: {
            name: 'targetAsset',
            in: 'query',
            required: false,
            description:
              'Filter transfers by target asset symbol (e.g., `usdc`, `eurc`, `usd`, `eur`).',
            example: 'usdc',
            schema: { type: 'string' },
          },
        }),
      sourceAddress: BlockchainAddressSchema.openapi({
        param: {
          name: 'sourceAddress',
          in: 'query',
          required: false,
          description:
            'Filter transfers by the on-chain address of the source. Cannot be combined with `accountId` or `sourceAccountId`.',
          example: '0x742d35Cc6634C0532925a3b844Bc454e4438f44e',
          schema: { $ref: '#/components/schemas/BlockchainAddress' },
        },
      }).exactOptional(),
      targetAddress: BlockchainAddressSchema.openapi({
        param: {
          name: 'targetAddress',
          in: 'query',
          required: false,
          description:
            'Filter transfers by the on-chain destination address of the target. Cannot be combined with `accountId`, `targetAccountId`, or `targetEmail`.',
          example: '0x833589fCD6eDb6E08f4c7C32D4f71b54bdA02913',
          schema: { $ref: '#/components/schemas/BlockchainAddress' },
        },
      }).exactOptional(),
      targetEmail: EmailSchema.openapi({
        param: {
          name: 'targetEmail',
          in: 'query',
          required: false,
          description:
            'Filter transfers by the email address of the target recipient. Cannot be combined with `accountId`, `targetAccountId`, or `targetAddress`.',
          example: 'recipient@example.com',
          schema: { $ref: '#/components/schemas/Email' },
        },
      }).exactOptional(),
      transferId: z
        .string()
        .regex(/^transfer_[a-f0-9\-]{36}$/)
        .exactOptional()
        .openapi({
          param: {
            name: 'transferId',
            in: 'query',
            required: false,
            description:
              'Filter to a specific transfer by ID. When provided, returns only the matching transfer and bypasses pagination. Cannot be combined with any other filter.',
            example: 'transfer_af2937b0-9846-4fe7-bfe9-ccc22d935114',
            schema: { type: 'string', pattern: '^transfer_[a-f0-9\\-]{36}$' },
          },
        }),
      pageSize: PageSizeParamsSchema,
      pageToken: PageTokenParamsSchema,
    }),
  },
  responses: {
    200: {
      description: 'Successfully listed transfers.',
      content: {
        'application/json': {
          schema: z
            .object({
              transfers: z.array(TransferSchema).openapi({ description: 'The list of transfers.' }),
            })
            .openapi({ required: ['transfers'] })
            .and(ListResponseSchema),
          examples: { page: ListTransfersResponseExample },
        },
      },
    },
    400: {
      description: 'Invalid request.',
      content: {
        'application/json': {
          schema: ErrorSchema,
          examples: {
            invalid_request: {
              value: { errorType: 'invalid_request', errorMessage: 'Invalid query parameters.' },
            },
            incompatible_filters: {
              summary: 'Incompatible filters',
              value: {
                errorType: 'invalid_request',
                errorMessage: "'transferId' cannot be combined with other filters.",
              },
            },
          },
        },
      },
    },
  },
  security: [{ apiKeyAuth: [] }],
})

export const postV2TransfersRoute = createRoute({
  method: 'post',
  path: '/v2/transfers',
  tags: ['Transfers'],
  summary: 'Create transfer',
  description:
    'Create a new transfer to move funds from a source to a target.\nAll transfers first transition to `quoted`. If `execute: false`, the transfer stays quoted until you call `/v2/transfers/{transferId}/execute`.\nIf `execute: true`, quoted status emits momentarily before the transfer moves to `processing`, where execution proceeds. Subscribe to the transfers webhook to  follow progress in real time instead of polling.',
  operationId: 'createTransfer',
  request: {
    headers: z.object({ 'X-Idempotency-Key': IdempotencyKeyParamsSchema }),
    body: {
      content: {
        'application/json': {
          schema: TransferRequestSchema,
          example: {
            source: { accountId: 'account_af2937b0-9846-4fe7-bfe9-ccc22d935114', asset: 'usd' },
            target: {
              address: '0x833589fCD6eDb6E08f4c7C32D4f71b54bdA02913',
              network: 'base',
              asset: 'usdc',
            },
            amount: '100.00',
            asset: 'usd',
            execute: false,
            validateOnly: false,
            metadata: { invoiceId: '12345', reference: 'Payment for invoice #12345' },
            travelRule: {
              isSelf: false,
              isIntermediary: true,
              attestVerifiedWalletOwnership: true,
              originator: {
                name: 'John Doe',
                address: {
                  line1: '123 Main St',
                  line2: 'Unit 201',
                  city: 'San Francisco',
                  state: 'California',
                  postCode: '94105',
                  countryCode: 'US',
                },
                financialInstitution: 'PayPal, Inc.',
                virtualAssetServiceProvider: {
                  identifier: '5493001KJTIIGC8Y1R17',
                  name: 'Fidelity Digital Asset Services, LLC',
                  address: {
                    line1: '123 Market St',
                    line2: 'Suite 400',
                    city: 'San Francisco',
                    state: 'California',
                    postCode: '94105',
                    countryCode: 'US',
                  },
                },
                personalId: '123-45-6789',
                dateOfBirth: { day: '15', month: '08', year: '1990' },
              },
              beneficiary: {
                name: 'Jane Smith',
                address: {
                  line1: '456 Oak Ave',
                  city: 'Paris',
                  postCode: '75001',
                  countryCode: 'FR',
                },
                walletType: 'custodial',
              },
            },
          },
        },
      },
    },
  },
  responses: {
    200: {
      description: 'Successfully created transfer.',
      content: {
        'application/json': {
          schema: TransferSchema,
          examples: { regular: RegularTransferQuotedExample, fx_quoted: FxTransferQuotedExample },
        },
      },
    },
    400: {
      description: 'Invalid request.',
      content: {
        'application/json': {
          schema: ErrorSchema,
          examples: {
            invalid_request: {
              value: { errorType: 'invalid_request', errorMessage: 'Invalid query parameters.' },
            },
          },
        },
      },
    },
    403: {
      description:
        'Customer is not authorized for one or more capabilities required by this action.',
      content: {
        'application/json': {
          schema: ErrorSchema,
          examples: {
            customer_not_authorized: {
              summary: 'Customer is not authorized for one or more required capabilities',
              value: {
                errorType: 'customer_not_authorized',
                errorMessage:
                  'Customer is not authorized for one or more capabilities required by this action.',
                unauthorizedCapabilities: [
                  'transferStablecoin',
                  'tradeStablecoin',
                  'tradeCrypto',
                  'custodyStablecoin',
                ],
              },
            },
          },
        },
      },
    },
    422: IdempotencyErrorResponse,
  },
  security: [{ apiKeyAuth: [] }],
})

