export const postV2TransfersTransferIdTravelRuleRoute = createRoute({
  method: 'post',
  path: '/v2/transfers/{transferId}/travel-rule',
  tags: ['Transfers'],
  summary: 'Submit deposit travel rule information',
  description:
    'Submit travel rule information for a deposit transfer held pending compliance review.\n\nRequired fields vary by jurisdiction and may include originator name, address, date of birth, personal ID, and VASP information.\n\nIf the submitted information satisfies all jurisdictional requirements, `status` will be `completed` and the transfer will proceed. Otherwise, `status` will be `incomplete` and `missingFields` will indicate which fields still need to be provided.',
  operationId: 'submitDepositTravelRule',
  request: {
    params: z.object({
      transferId: z
        .string()
        .regex(/^transfer_[a-f0-9\-]{36}$/)
        .openapi({
          param: {
            name: 'transferId',
            in: 'path',
            required: true,
            description: 'The unique identifier of the transfer.',
            schema: {
              type: 'string',
              pattern: '^transfer_[a-f0-9\\-]{36}$',
              example: 'transfer_af2937b0-9846-4fe7-bfe9-ccc22d935114',
            },
          },
          example: 'transfer_af2937b0-9846-4fe7-bfe9-ccc22d935114',
        }),
    }),
    headers: z.object({ 'X-Idempotency-Key': IdempotencyKeyParamsSchema }),
    body: {
      content: {
        'application/json': {
          schema: DepositTravelRuleRequestSchema,
          example: {
            isSelf: false,
            isIntermediary: true,
            attestVerifiedWalletOwnership: true,
            originator: {
              name: 'John Doe',
              address: {
                line1: '123 Main St',
                city: 'San Francisco',
                state: 'CA',
                postCode: '94105',
                countryCode: 'US',
              },
              financialInstitution: 'PayPal, Inc.',
              virtualAssetServiceProvider: {
                identifier: '5493001KJTIIGC8Y1R17',
                name: 'Fidelity Digital Asset Services, LLC',
              },
              personalId: '123-45-6789',
              dateOfBirth: { day: '15', month: '08', year: '1990' },
              walletType: 'custodial',
            },
            beneficiary: { name: 'Jane Smith' },
          },
        },
      },
    },
  },
  responses: {
    200: {
      description: 'Successfully submitted travel rule information.',
      content: {
        'application/json': {
          schema: DepositTravelRuleResponseSchema,
          examples: {
            incomplete: {
              value: { status: 'incomplete', missingFields: ['originator.dateOfBirth'] },
            },
            completed: { value: { status: 'completed', missingFields: [] } },
          },
        },
      },
    },
    400: {
      description: 'Invalid request.',
      content: {
        'application/json': {
          schema: ErrorSchema,
          examples: {
            invalid_request: {
              value: { errorType: 'invalid_request', errorMessage: 'Invalid request body.' },
            },
          },
        },
      },
    },
    404: {
      description: 'Transfer not found.',
      content: {
        'application/json': {
          schema: ErrorSchema,
          examples: {
            not_found: {
              summary: 'Transfer not found',
              value: { errorType: 'not_found', errorMessage: 'Transfer not found.' },
            },
          },
        },
      },
    },
    422: IdempotencyErrorResponse,
  },
  security: [{ apiKeyAuth: [] }],
})

