export const getV2DisbursementsRoute = createRoute({
  method: 'get',
  path: '/v2/disbursements',
  tags: ['Disbursements'],
  summary: 'List disbursements',
  description:
    'Returns a paginated list of disbursements accessible to your API key. Filter by `status`, `sourceAccountId`, or `externalReferenceId`.',
  operationId: 'listDisbursements',
  request: {
    query: z.object({
      pageSize: PageSizeParamsSchema,
      pageToken: PageTokenParamsSchema,
      status: PaymentActionStatusSchema.openapi({
        param: {
          name: 'status',
          in: 'query',
          required: false,
          description: 'Filter disbursements by status.',
          schema: { $ref: '#/components/schemas/PaymentActionStatus' },
          example: 'pending',
        },
      }).exactOptional(),
      sourceAccountId: z
        .string()
        .exactOptional()
        .openapi({
          param: {
            name: 'sourceAccountId',
            in: 'query',
            required: false,
            description: 'Filter disbursements by the source CDP account ID.',
            schema: { type: 'string' },
            example: 'account_af2937b0-9846-4fe7-bfe9-ccc22d935114',
          },
        }),
      externalReferenceId: z
        .string()
        .exactOptional()
        .openapi({
          param: {
            name: 'externalReferenceId',
            in: 'query',
            required: false,
            description: 'Filter disbursements by the client-supplied external reference ID.',
            schema: { type: 'string' },
            example: 'disbursement-2026-04-1234',
          },
        }),
    }),
  },
  responses: {
    200: {
      description: 'Successfully listed disbursements.',
      content: {
        'application/json': {
          schema: z
            .object({
              disbursements: z
                .array(DisbursementSchema)
                .openapi({ description: 'The list of disbursements.' }),
            })
            .openapi({ required: ['disbursements'] })
            .and(ListResponseSchema)
            .openapi({
              example: {
                disbursements: [
                  {
                    disbursementId: 'disbursement_82c879c1-84e1-44ed-a8c2-1ac239cf09ad',
                    source: {
                      accountId: 'account_af2937b0-9846-4fe7-bfe9-ccc22d935114',
                      asset: 'usdc',
                    },
                    target: { coinbaseUserId: 'coinbase_user_abc123' },
                    amount: '25.00',
                    asset: 'usdc',
                    status: 'succeeded',
                    reason: 'Goodwill disbursement for delayed shipment.',
                    externalReferenceId: 'disbursement-2026-04-1234',
                    customerDisplay: { merchantName: 'Acme Store', referenceCode: 'REF-ABC123' },
                    metadata: { customer_id: 'cust_12345', order_id: 'order_67890' },
                    onchainTransactions: [
                      {
                        transactionHash:
                          '0xabc123def456789012345678901234567890abcdef1234567890abcdef123456',
                        network: 'base',
                      },
                    ],
                    createdAt: '2026-04-17T17:00:00.000Z',
                    updatedAt: '2026-04-17T17:05:00.000Z',
                  },
                ],
                nextPageToken: 'eyJsYXN0X2lkIjogImFiYzEyMyIsICJ0aW1lc3RhbXAiOiAxNzA3ODIzNzAxfQ==',
              },
            }),
        },
      },
    },
    400: {
      description: 'Invalid request.',
      content: {
        'application/json': {
          schema: ErrorSchema,
          examples: {
            invalid_request: {
              value: { errorType: 'invalid_request', errorMessage: 'Invalid query parameters.' },
            },
          },
        },
      },
    },
    500: InternalServerErrorResponse,
    502: BadGatewayErrorResponse,
    503: ServiceUnavailableErrorResponse,
  },
  security: [{ apiKeyAuth: [] }],
})

