export const postV2EndUsersAuthValidateTokenRoute = createRoute({
  method: 'post',
  path: '/v2/end-users/auth/validate-token',
  tags: ['End User Account Management'],
  summary: 'Validate end user access token',
  description:
    "Validates the end user's access token and returns the end user's information. Returns an error if the access token is invalid or expired.\n\nThis API is intended to be used by the developer's own backend, and is authenticated using the developer's CDP API key.",
  operationId: 'validateEndUserAccessToken',
  request: {
    body: {
      content: {
        'application/json': {
          schema: z
            .object({
              accessToken: z
                .string()
                .openapi({
                  description: 'The access token in JWT format to verify.',
                  example:
                    'eyJhbGciOiJFUzI1NiIsImtpZCI6IjA1ZGNmYTU1LWY1NzktNDg5YS1iNThhLTFlMDI5Nzk0N2VlNiIsInR5cCI6IkpXVCJ9..1SU0pOy-WR002qUw4hd_UmZWRSLz-ZL6v7PvQvZMKVE6a51x_tqeUeRGaTGuYl1whg0eccMObmK7FqXKRH6E4g',
                }),
            })
            .openapi({
              description: "The request body for a developer to verify an end user's access token.",
              required: ['accessToken'],
            }),
        },
      },
    },
  },
  responses: {
    200: {
      description:
        "Confirms that the access token is valid and returns the end user's information.",
      content: { 'application/json': { schema: EndUserSchema } },
    },
    400: {
      description: 'Request body is invalid.',
      content: {
        'application/json': {
          schema: ErrorSchema,
          examples: {
            invalid_request: {
              value: { errorType: 'invalid_request', errorMessage: 'Missing access token.' },
            },
          },
        },
      },
    },
    401: {
      description:
        'Request is not properly authenticated, or the access token is invalid or expired.',
      content: {
        'application/json': {
          schema: ErrorSchema,
          examples: {
            unauthorized: {
              value: {
                errorType: 'unauthorized',
                errorMessage: 'Invalid JWT issuer: not-cdp-api, expected: cdp-api.',
              },
            },
          },
        },
      },
    },
    404: {
      description: 'End user not found.',
      content: {
        'application/json': {
          schema: ErrorSchema,
          examples: {
            not_found: { value: { errorType: 'not_found', errorMessage: 'End user not found.' } },
          },
        },
      },
    },
    500: InternalServerErrorResponse,
  },
  security: [{ apiKeyAuth: [] }],
})

