export const getV2EndUsersLookupRoute = createRoute({
  method: 'get',
  path: '/v2/end-users/lookup',
  tags: ['End User Account Management'],
  summary: 'Look up end users by identity',
  description:
    "Looks up end users. Exactly one lookup type must be provided per request:\n\n- **email**: searches across all email-based authentication methods\n  (email, Google, Apple, GitHub). May return multiple end users if the\n  same email address appears across different auth methods.\n\n- **oauthProvider + oauthSubject**: looks up a user by their OAuth\n  provider and subject (the `sub` claim from the provider's ID token).\n  Both params must be provided together.\n\n- **phoneNumber**: looks up a user by their SMS-verified phone number.\n- **siweAddress**: looks up a user by the Ethereum address they authenticated\n  with via Sign In With Ethereum (EIP-4361).\n\n\nReturns all matching end users. If no end users match, an empty array is returned.\n\nThis API is intended to be used by the developer's own backend, and is authenticated using the developer's CDP API key.",
  operationId: 'lookupEndUser',
  request: {
    query: z.object({
      email: EmailSchema.openapi({
        param: {
          name: 'email',
          in: 'query',
          required: false,
          description:
            'The email address to search for across all email-based authentication methods.',
          schema: { $ref: '#/components/schemas/Email' },
          example: 'user@example.com',
        },
      }).exactOptional(),
      oauthProvider: OAuth2ProviderTypeSchema.openapi({
        param: {
          name: 'oauthProvider',
          in: 'query',
          required: false,
          description:
            'The OAuth provider to search by. Must be provided together with oauthSubject.',
          schema: { $ref: '#/components/schemas/OAuth2ProviderType' },
          example: 'google',
        },
      }).exactOptional(),
      oauthSubject: z
        .string()
        .exactOptional()
        .openapi({
          param: {
            name: 'oauthSubject',
            in: 'query',
            required: false,
            description:
              "The OAuth subject (the `sub` claim from the provider's ID token). Must be provided together with oauthProvider.",
            schema: { type: 'string' },
            example: '1234567890',
          },
        }),
      phoneNumber: PhoneNumberSchema.openapi({
        param: {
          name: 'phoneNumber',
          in: 'query',
          required: false,
          description:
            'The E.164-formatted phone number to search for. Must be URL-encoded when passed as a query parameter (e.g. `+14155552671` → `%2B14155552671`).',
          schema: { $ref: '#/components/schemas/PhoneNumber' },
          example: '+14155552671',
        },
      }).exactOptional(),
      siweAddress: BlockchainAddressSchema.openapi({
        param: {
          name: 'siweAddress',
          in: 'query',
          required: false,
          description:
            'The ERC-55 checksummed Ethereum address to search for. Looks up a user by the address they authenticated with via Sign In With Ethereum (EIP-4361).',
          schema: { $ref: '#/components/schemas/BlockchainAddress' },
          example: '0x742d35Cc6634C0532925a3b844Bc454e4438f44e',
        },
      }).exactOptional(),
    }),
  },
  responses: {
    200: {
      description: 'Successfully looked up end users.',
      content: {
        'application/json': {
          schema: z
            .object({
              endUsers: z
                .array(EndUserSchema)
                .openapi({ description: 'The list of end users matching the lookup.' }),
            })
            .openapi({ required: ['endUsers'] }),
          examples: {
            email_match: {
              summary: 'End user found by email',
              value: {
                endUsers: [
                  {
                    userId: 'user-001',
                    authenticationMethods: [{ type: 'email', email: 'user@example.com' }],
                    evmAccounts: [],
                    evmAccountObjects: [],
                    evmSmartAccounts: [],
                    evmSmartAccountObjects: [],
                    solanaAccounts: [],
                    solanaAccountObjects: [],
                    createdAt: '2025-11-17T10:00:00Z',
                  },
                ],
              },
            },
            multiple_email_matches: {
              summary: 'Multiple end users with same email across auth methods',
              value: {
                endUsers: [
                  {
                    userId: 'user-001',
                    authenticationMethods: [{ type: 'email', email: 'user@example.com' }],
                    evmAccounts: [],
                    evmAccountObjects: [],
                    evmSmartAccounts: [],
                    evmSmartAccountObjects: [],
                    solanaAccounts: [],
                    solanaAccountObjects: [],
                    createdAt: '2025-11-17T10:00:00Z',
                  },
                  {
                    userId: 'user-002',
                    authenticationMethods: [
                      { type: 'google', sub: 'google-sub-123', email: 'user@example.com' },
                    ],
                    evmAccounts: [],
                    evmAccountObjects: [],
                    evmSmartAccounts: [],
                    evmSmartAccountObjects: [],
                    solanaAccounts: [],
                    solanaAccountObjects: [],
                    createdAt: '2025-11-17T11:00:00Z',
                  },
                ],
              },
            },
            oauth_match: {
              summary: 'End user found by OAuth subject',
              value: {
                endUsers: [
                  {
                    userId: 'user-003',
                    authenticationMethods: [
                      { type: 'google', sub: '1234567890', email: 'user@example.com' },
                    ],
                    evmAccounts: [],
                    evmAccountObjects: [],
                    evmSmartAccounts: [],
                    evmSmartAccountObjects: [],
                    solanaAccounts: [],
                    solanaAccountObjects: [],
                    createdAt: '2025-11-17T12:00:00Z',
                  },
                ],
              },
            },
            phone_match: {
              summary: 'End user found by phone number',
              value: {
                endUsers: [
                  {
                    userId: 'user-004',
                    authenticationMethods: [{ type: 'sms', phoneNumber: '+14155552671' }],
                    evmAccounts: [],
                    evmAccountObjects: [],
                    evmSmartAccounts: [],
                    evmSmartAccountObjects: [],
                    solanaAccounts: [],
                    solanaAccountObjects: [],
                    createdAt: '2025-11-17T13:00:00Z',
                  },
                ],
              },
            },
            siwe_match: {
              summary: 'End user found by SIWE address',
              value: {
                endUsers: [
                  {
                    userId: 'user-005',
                    authenticationMethods: [
                      { type: 'siwe', address: '0x742d35Cc6634C0532925a3b844Bc454e4438f44e' },
                    ],
                    evmAccounts: [],
                    evmAccountObjects: [],
                    evmSmartAccounts: [],
                    evmSmartAccountObjects: [],
                    solanaAccounts: [],
                    solanaAccountObjects: [],
                    createdAt: '2025-11-17T14:00:00Z',
                  },
                ],
              },
            },
            no_matches: { summary: 'No end users found', value: { endUsers: [] } },
          },
        },
      },
    },
    400: {
      description: 'Invalid request.',
      content: {
        'application/json': {
          schema: ErrorSchema,
          examples: {
            no_lookup_param: {
              summary: 'No lookup parameter provided',
              value: {
                errorType: 'invalid_request',
                errorMessage:
                  'Exactly one lookup type must be provided: email, phoneNumber, siweAddress, or oauthProvider+oauthSubject.',
              },
            },
            multiple_lookup_params: {
              summary: 'Multiple lookup parameters provided',
              value: {
                errorType: 'invalid_request',
                errorMessage:
                  'Exactly one lookup type must be provided: email, phoneNumber, siweAddress, or oauthProvider+oauthSubject.',
              },
            },
            oauth_missing_subject: {
              summary: 'oauthProvider provided without oauthSubject',
              value: {
                errorType: 'invalid_request',
                errorMessage: 'oauthProvider and oauthSubject must be provided together.',
              },
            },
          },
        },
      },
    },
    401: UnauthorizedErrorResponse,
    500: InternalServerErrorResponse,
  },
  security: [{ apiKeyAuth: [] }],
})

