export const postV2EmbeddedWalletApiEndUsersUserIdEvmSignTransactionRoute = createRoute({
  method: 'post',
  path: '/v2/embedded-wallet-api/end-users/{userId}/evm/sign/transaction',
  tags: ['End User Accounts'],
  summary: 'Sign transaction via end user EVM account',
  description:
    'Signs a transaction with the given end user EVM account.\nThe transaction should be serialized as a hex string using [RLP](https://ethereum.org/en/developers/docs/data-structures-and-encoding/rlp/).\n\nThe transaction must be an [EIP-1559 dynamic fee transaction](https://github.com/ethereum/EIPs/blob/master/EIPS/eip-1559.md). The developer is responsible for ensuring that the unsigned transaction is valid, as the API will not validate the transaction.',
  operationId: 'signEvmTransactionWithEndUserAccount',
  request: {
    headers: z.object({
      'X-Wallet-Auth': XWalletAuthOptionalParamsSchema,
      'X-Idempotency-Key': IdempotencyKeyParamsSchema,
      'X-Developer-Auth': XDeveloperAuthParamsSchema,
    }),
    params: z.object({
      userId: z
        .string()
        .regex(/^[a-zA-Z0-9-]{1,100}$/)
        .openapi({
          param: {
            name: 'userId',
            description: 'The ID of the end user.',
            in: 'path',
            required: true,
            schema: {
              type: 'string',
              pattern: '^[a-zA-Z0-9-]{1,100}$',
              example: 'e051beeb-7163-4527-a5b6-35e301529ff2',
            },
          },
          example: 'e051beeb-7163-4527-a5b6-35e301529ff2',
        }),
    }),
    query: z.object({ projectID: ProjectIDOptionalParamsSchema }),
    body: {
      content: {
        'application/json': {
          schema: z
            .object({
              address: z
                .string()
                .regex(/^0x[0-9a-fA-F]{40}$/)
                .openapi({
                  description:
                    'The 0x-prefixed address of the EVM account belonging to the end user.',
                  example: '0x742d35Cc6634C0532925a3b844Bc454e4438f44e',
                }),
              transaction: z
                .string()
                .openapi({
                  description: 'The RLP-encoded transaction to sign, as a 0x-prefixed hex string.',
                  example:
                    '0xf86b098505d21dba00830334509431415daf58e2c6b7323b4c58712fd92952145da79018080',
                }),
              walletSecretId: z
                .string()
                .regex(/^[a-zA-Z0-9-]{1,100}$/)
                .exactOptional()
                .openapi({
                  description:
                    'Required when not using delegated signing. The ID of the Temporary Wallet Secret that was used to sign the X-Wallet-Auth Header.',
                  example: 'e051beeb-7163-4527-a5b6-35e301529ff2',
                }),
            })
            .openapi({ required: ['address', 'transaction'] }),
        },
      },
    },
  },
  responses: {
    200: {
      description: 'Successfully signed transaction.',
      content: {
        'application/json': {
          schema: z
            .object({
              signedTransaction: z
                .string()
                .openapi({
                  description: 'The RLP-encoded signed transaction, as a 0x-prefixed hex string.',
                  example:
                    '0x1b0c9cf8cd4554c6c6d9e7311e88f1be075d7f25b418a044f4bf2c0a42a93e212ad0a8b54de9e0b5f7e3812de3f2c6cc79aa8c3e1c02e7ad14b4a8f42012c2c01b',
                }),
            })
            .openapi({ required: ['signedTransaction'] }),
        },
      },
    },
    400: {
      description: 'Invalid request.',
      content: {
        'application/json': {
          schema: ErrorSchema,
          examples: {
            malformed_transaction: {
              value: {
                errorType: 'malformed_transaction',
                errorMessage: 'Malformed unsigned transaction.',
              },
            },
          },
        },
      },
    },
    401: UnauthorizedErrorResponse,
    402: PaymentMethodRequiredErrorResponse,
    403: DelegationForbiddenErrorResponse,
    404: {
      description: 'Not found.',
      content: {
        'application/json': {
          schema: ErrorSchema,
          examples: {
            not_found: {
              value: {
                errorType: 'not_found',
                errorMessage: 'EVM account with the given address not found.',
              },
            },
          },
        },
      },
    },
    409: AlreadyExistsErrorResponse,
    422: IdempotencyErrorResponse,
    500: InternalServerErrorResponse,
    502: BadGatewayErrorResponse,
    503: ServiceUnavailableErrorResponse,
  },
  security: [{ endUserAuth: [] }, { apiKeyAuth: [] }],
})

export const postV2EmbeddedWalletApiEndUsersUserIdEvmSendTransactionRoute = createRoute({
  method: 'post',
  path: '/v2/embedded-wallet-api/end-users/{userId}/evm/send/transaction',
  tags: ['End User Accounts'],
  summary: 'Send transaction via end user EVM account',
  description:
    'Signs a transaction with the given end user EVM account and sends it to the indicated supported network. This API handles nonce management and gas estimation, leaving the developer to provide only the minimal set of fields necessary to send the transaction. The transaction should be serialized as a hex string using [RLP](https://ethereum.org/en/developers/docs/data-structures-and-encoding/rlp/).\n\nThe transaction must be an [EIP-1559 dynamic fee transaction](https://github.com/ethereum/EIPs/blob/master/EIPS/eip-1559.md).\n\n\n**Transaction fields and API behavior**\n\n- `to` *(Required)*: The address of the contract or account to send the transaction to.\n- `chainId` *(Ignored)*: The value of the `chainId` field in the transaction is ignored.\n  The transaction will be sent to the network indicated by the `network` field in the request body.\n\n- `nonce` *(Optional)*: The nonce to use for the transaction. If not provided, the API will assign\n   a nonce to the transaction based on the current state of the account.\n\n- `maxPriorityFeePerGas` *(Optional)*: The maximum priority fee per gas to use for the transaction.\n   If not provided, the API will estimate a value based on current network conditions.\n\n- `maxFeePerGas` *(Optional)*: The maximum fee per gas to use for the transaction.\n   If not provided, the API will estimate a value based on current network conditions.\n\n- `gasLimit` *(Optional)*: The gas limit to use for the transaction. If not provided, the API will estimate a value\n  based on the `to` and `data` fields of the transaction.\n\n- `value` *(Optional)*: The amount of ETH, in wei, to send with the transaction.\n- `data` *(Optional)*: The data to send with the transaction; only used for contract calls.\n- `accessList` *(Optional)*: The access list to use for the transaction.',
  operationId: 'sendEvmTransactionWithEndUserAccount',
  request: {
    headers: z.object({
      'X-Wallet-Auth': XWalletAuthOptionalParamsSchema,
      'X-Idempotency-Key': IdempotencyKeyParamsSchema,
      'X-Developer-Auth': XDeveloperAuthParamsSchema,
    }),
    params: z.object({
      userId: z
        .string()
        .regex(/^[a-zA-Z0-9-]{1,100}$/)
        .openapi({
          param: {
            name: 'userId',
            description: 'The ID of the end user.',
            in: 'path',
            required: true,
            schema: {
              type: 'string',
              pattern: '^[a-zA-Z0-9-]{1,100}$',
              example: 'e051beeb-7163-4527-a5b6-35e301529ff2',
            },
          },
          example: 'e051beeb-7163-4527-a5b6-35e301529ff2',
        }),
    }),
    query: z.object({ projectID: ProjectIDOptionalParamsSchema }),
    body: {
      content: {
        'application/json': {
          schema: z
            .object({
              address: z
                .string()
                .regex(/^0x[0-9a-fA-F]{40}$/)
                .openapi({
                  description:
                    'The 0x-prefixed address of the EVM account belonging to the end user.',
                  example: '0x742d35Cc6634C0532925a3b844Bc454e4438f44e',
                }),
              network: z
                .enum([
                  'base',
                  'base-sepolia',
                  'ethereum',
                  'ethereum-sepolia',
                  'avalanche',
                  'polygon',
                  'optimism',
                  'arbitrum',
                  'arbitrum-sepolia',
                  'world',
                  'world-sepolia',
                ])
                .openapi({
                  description: 'The network to send the transaction to.',
                  example: 'base-sepolia',
                }),
              walletSecretId: z
                .string()
                .regex(/^[a-zA-Z0-9-]{1,100}$/)
                .exactOptional()
                .openapi({
                  description:
                    'Required when not using delegated signing. The ID of the Temporary Wallet Secret that was used to sign the X-Wallet-Auth Header.',
                  example: 'e051beeb-7163-4527-a5b6-35e301529ff2',
                }),
              transaction: z
                .string()
                .openapi({
                  description:
                    'The RLP-encoded transaction to sign and send, as a 0x-prefixed hex string.',
                  example:
                    '0xf86b098505d21dba00830334509431415daf58e2c6b7323b4c58712fd92952145da79018080',
                }),
            })
            .openapi({ required: ['address', 'transaction', 'network'] }),
        },
      },
    },
  },
  responses: {
    200: {
      description: 'Successfully signed and sent transaction.',
      content: {
        'application/json': {
          schema: z
            .object({
              transactionHash: z
                .string()
                .openapi({
                  description: 'The hash of the transaction, as a 0x-prefixed hex string.',
                  example: '0xf8f98fb6726fc936f24b2007df5cb20e2b8444ff3dfaa2a929335f432a9be2e7',
                }),
            })
            .openapi({ required: ['transactionHash'] }),
        },
      },
    },
    400: {
      description: 'Invalid request.',
      content: {
        'application/json': {
          schema: ErrorSchema,
          examples: {
            malformed_transaction: {
              value: {
                errorType: 'malformed_transaction',
                errorMessage: 'Malformed unsigned transaction.',
              },
            },
          },
        },
      },
    },
    401: UnauthorizedErrorResponse,
    402: PaymentMethodRequiredErrorResponse,
    403: DelegationForbiddenErrorResponse,
    404: {
      description: 'Not found.',
      content: {
        'application/json': {
          schema: ErrorSchema,
          examples: {
            not_found: {
              value: {
                errorType: 'not_found',
                errorMessage: 'EVM account with the given address not found.',
              },
            },
          },
        },
      },
    },
    409: AlreadyExistsErrorResponse,
    422: IdempotencyErrorResponse,
    500: InternalServerErrorResponse,
    502: BadGatewayErrorResponse,
    503: ServiceUnavailableErrorResponse,
  },
  security: [{ endUserAuth: [] }, { apiKeyAuth: [] }],
})

export const postV2EmbeddedWalletApiEndUsersUserIdEvmAddressSendAssetRoute = createRoute({
  method: 'post',
  path: '/v2/embedded-wallet-api/end-users/{userId}/evm/{address}/send/{asset}',
  tags: ['End User Accounts'],
  summary: 'Send USDC on EVM',
  description:
    'Sends USDC from an end user\'s EVM account (EOA or Smart Account) to a recipient address on a supported EVM network. This endpoint simplifies USDC transfers by automatically handling contract resolution, decimal conversion, gas estimation, and transaction encoding.\nThe `amount` field accepts human-readable amounts as decimal strings (e.g., "1.5", "25.50").',
  operationId: 'sendEvmAssetWithEndUserAccount',
  request: {
    headers: z.object({
      'X-Wallet-Auth': XWalletAuthOptionalParamsSchema,
      'X-Idempotency-Key': IdempotencyKeyParamsSchema,
      'X-Developer-Auth': XDeveloperAuthParamsSchema,
    }),
    params: z.object({
      userId: z
        .string()
        .regex(/^[a-zA-Z0-9-]{1,100}$/)
        .openapi({
          param: {
            name: 'userId',
            in: 'path',
            required: true,
            description: 'The ID of the end user.',
            schema: { type: 'string', pattern: '^[a-zA-Z0-9-]{1,100}$' },
            example: 'e051beeb-7163-4527-a5b6-35e301529ff2',
          },
        }),
      address: BlockchainAddressSchema.openapi({
        param: {
          name: 'address',
          description:
            'The 0x-prefixed address of the EVM account (EOA or Smart Account) to send USDC from. The address does not need to be checksummed.',
          in: 'path',
          required: true,
          schema: {
            allOf: [{ $ref: '#/components/schemas/BlockchainAddress' }],
            pattern: '^0x[0-9a-fA-F]{40}$',
          },
          example: '0x742d35Cc6634C0532925a3b844Bc454e4438f44e',
        },
      }),
      asset: AssetSchema.openapi({
        param: {
          name: 'asset',
          in: 'path',
          required: true,
          description: 'The asset to send. Currently only "usdc" is supported.',
          schema: { allOf: [{ $ref: '#/components/schemas/Asset' }], enum: ['usdc'] },
          example: 'usdc',
        },
      }),
    }),
    query: z.object({ projectID: ProjectIDOptionalParamsSchema }),
    body: {
      content: {
        'application/json': {
          schema: z
            .object({
              to: BlockchainAddressSchema.openapi({
                description: 'The 0x-prefixed address of the recipient.',
                example: '0x1234567890123456789012345678901234567890',
              }),
              amount: z
                .string()
                .min(1)
                .max(32)
                .openapi({
                  description:
                    'The amount of USDC to send as a decimal string (e.g., "1.5" or "25.50").',
                  example: '1.50',
                }),
              network: z
                .enum([
                  'base',
                  'base-sepolia',
                  'ethereum',
                  'ethereum-sepolia',
                  'avalanche',
                  'polygon',
                  'optimism',
                  'arbitrum',
                  'arbitrum-sepolia',
                  'world',
                  'world-sepolia',
                ])
                .openapi({
                  description: 'The EVM network to send USDC on.',
                  example: 'base-sepolia',
                }),
              useCdpPaymaster: z
                .boolean()
                .exactOptional()
                .openapi({
                  description:
                    'Whether to use CDP Paymaster to sponsor gas fees. Only applicable for EVM Smart Accounts. When true, the transaction gas will be paid by the Paymaster, allowing users to send USDC without holding native gas tokens. Ignored for EOA accounts. Cannot be used together with `paymasterUrl`.',
                  example: true,
                }),
              paymasterUrl: UrlSchema.exactOptional().openapi({
                description:
                  "Optional custom Paymaster URL to use for gas sponsorship. Only applicable for EVM Smart Accounts. This allows you to use your own Paymaster service instead of CDP's Paymaster. Cannot be used together with `useCdpPaymaster`.",
                example: 'https://api.developer.coinbase.com/rpc/v1/base/AbCdEf123456',
              }),
              paymasterContext: PaymasterContextSchema.exactOptional(),
              walletSecretId: z
                .string()
                .regex(/^[a-zA-Z0-9-]{1,100}$/)
                .exactOptional()
                .openapi({
                  description:
                    'Required when not using delegated signing. The ID of the Temporary Wallet Secret that was used to sign the X-Wallet-Auth Header.',
                  example: 'e051beeb-7163-4527-a5b6-35e301529ff2',
                }),
            })
            .openapi({ required: ['to', 'amount', 'network'] }),
          examples: {
            send_usdc_eoa: {
              summary: 'Send USDC from EOA',
              value: {
                to: '0x1234567890123456789012345678901234567890',
                amount: '25.50',
                network: 'base-sepolia',
                walletSecretId: 'e051beeb-7163-4527-a5b6-35e301529ff2',
              },
            },
            send_usdc_smart_account_cdp_paymaster: {
              summary: 'Send USDC from Smart Account with CDP Paymaster',
              value: {
                to: '0x1234567890123456789012345678901234567890',
                amount: '10.00',
                network: 'base-sepolia',
                useCdpPaymaster: true,
                walletSecretId: 'e051beeb-7163-4527-a5b6-35e301529ff2',
              },
            },
            send_usdc_smart_account_custom_paymaster: {
              summary: 'Send USDC from Smart Account with custom Paymaster',
              value: {
                to: '0x1234567890123456789012345678901234567890',
                amount: '15.00',
                network: 'base-sepolia',
                paymasterUrl: 'https://api.developer.coinbase.com/rpc/v1/base/AbCdEf123456',
                walletSecretId: 'e051beeb-7163-4527-a5b6-35e301529ff2',
              },
            },
          },
        },
      },
    },
  },
  responses: {
    200: {
      description: 'Successfully sent transaction.',
      content: {
        'application/json': {
          schema: z
            .object({
              transactionHash: z
                .string()
                .nullable()
                .exactOptional()
                .openapi({
                  description:
                    'The hash of the transaction, as a 0x-prefixed hex string. Populated for EOA accounts. Null for Smart Accounts (use userOpHash instead).',
                  example: '0xf8f98fb6726fc936f24b2007df5cb20e2b8444ff3dfaa2a929335f432a9be2e7',
                }),
              userOpHash: z
                .string()
                .nullable()
                .exactOptional()
                .openapi({
                  description:
                    'The hash of the user operation, as a 0x-prefixed hex string. Populated for Smart Accounts. Null for EOA accounts (use transactionHash instead).',
                  example: '0x1234567890abcdef1234567890abcdef1234567890abcdef1234567890abcdef',
                }),
            })
            .openapi({ required: [] }),
          examples: {
            eoa_transfer: {
              summary: 'EOA transfer response',
              value: {
                transactionHash:
                  '0xf8f98fb6726fc936f24b2007df5cb20e2b8444ff3dfaa2a929335f432a9be2e7',
                userOpHash: null,
              },
            },
            smart_account_transfer: {
              summary: 'Smart Account transfer response',
              value: {
                transactionHash: null,
                userOpHash: '0x1234567890abcdef1234567890abcdef1234567890abcdef1234567890abcdef',
              },
            },
          },
        },
      },
    },
    400: {
      description: 'Invalid request.',
      content: {
        'application/json': {
          schema: ErrorSchema,
          examples: {
            invalid_amount: {
              value: {
                errorType: 'invalid_request',
                errorMessage: 'Invalid amount format. Amount must be a valid decimal string.',
                errorLink: 'https://docs.cdp.coinbase.com/api-reference/v2/errors#invalid-request',
              },
            },
            invalid_network: {
              value: {
                errorType: 'invalid_request',
                errorMessage: 'Unsupported network for USDC transfers.',
                errorLink: 'https://docs.cdp.coinbase.com/api-reference/v2/errors#invalid-request',
              },
            },
            invalid_asset: {
              value: {
                errorType: 'invalid_request',
                errorMessage: "Unsupported asset. Currently only 'usdc' is supported.",
                errorLink: 'https://docs.cdp.coinbase.com/api-reference/v2/errors#invalid-request',
              },
            },
            insufficient_balance: {
              value: {
                errorType: 'invalid_request',
                errorMessage: 'Account has insufficient USDC balance to complete the transfer.',
                errorLink: 'https://docs.cdp.coinbase.com/api-reference/v2/errors#invalid-request',
              },
            },
            conflicting_paymaster: {
              value: {
                errorType: 'invalid_request',
                errorMessage:
                  "Cannot specify both 'useCdpPaymaster' and 'paymasterUrl'. Please use only one.",
                errorLink:
                  'https://docs.cdp.coinbase.com/embedded-wallets/evm-features/smart-accounts#gas-sponsorship-with-paymaster',
              },
            },
            paymaster_context_without_paymaster: {
              value: {
                errorType: 'invalid_request',
                errorMessage:
                  'paymasterContext requires a paymaster: set paymasterUrl or useCdpPaymaster.',
                errorLink:
                  'https://docs.cdp.coinbase.com/embedded-wallets/evm-features/smart-accounts#gas-sponsorship-with-paymaster',
              },
            },
          },
        },
      },
    },
    401: UnauthorizedErrorResponse,
    402: PaymentMethodRequiredErrorResponse,
    403: DelegationForbiddenErrorResponse,
    404: {
      description: 'Not found.',
      content: {
        'application/json': {
          schema: ErrorSchema,
          examples: {
            not_found: {
              value: {
                errorType: 'not_found',
                errorMessage: 'EVM account with the given address not found.',
                errorLink: 'https://docs.cdp.coinbase.com/api-reference/v2/errors#not-found',
              },
            },
          },
        },
      },
    },
    422: IdempotencyErrorResponse,
    500: InternalServerErrorResponse,
    502: BadGatewayErrorResponse,
    503: ServiceUnavailableErrorResponse,
  },
  security: [{ endUserAuth: [] }, { apiKeyAuth: [] }],
})

export const postV2EmbeddedWalletApiEndUsersUserIdEvmSignMessageRoute = createRoute({
  method: 'post',
  path: '/v2/embedded-wallet-api/end-users/{userId}/evm/sign/message',
  tags: ['End User Accounts'],
  summary: 'Sign EIP-191 message via end user EVM account',
  description:
    'Signs an [EIP-191](https://eips.ethereum.org/EIPS/eip-191) message with the given end user EVM account.\n\nPer the specification, the message in the request body is prepended with `0x19 <0x45 (E)> <thereum Signed Message:\\n" + len(message)>` before being signed.',
  operationId: 'signEvmMessageWithEndUserAccount',
  request: {
    headers: z.object({
      'X-Wallet-Auth': XWalletAuthOptionalParamsSchema,
      'X-Idempotency-Key': IdempotencyKeyParamsSchema,
      'X-Developer-Auth': XDeveloperAuthParamsSchema,
    }),
    params: z.object({
      userId: z
        .string()
        .regex(/^[a-zA-Z0-9-]{1,100}$/)
        .openapi({
          param: {
            name: 'userId',
            description: 'The ID of the end user.',
            in: 'path',
            required: true,
            schema: {
              type: 'string',
              pattern: '^[a-zA-Z0-9-]{1,100}$',
              example: 'e051beeb-7163-4527-a5b6-35e301529ff2',
            },
          },
          example: 'e051beeb-7163-4527-a5b6-35e301529ff2',
        }),
    }),
    query: z.object({ projectID: ProjectIDOptionalParamsSchema }),
    body: {
      content: {
        'application/json': {
          schema: z
            .object({
              address: z
                .string()
                .regex(/^0x[0-9a-fA-F]{40}$/)
                .openapi({
                  description:
                    'The 0x-prefixed address of the EVM account belonging to the end user.',
                  example: '0x742d35Cc6634C0532925a3b844Bc454e4438f44e',
                }),
              message: z
                .string()
                .openapi({ description: 'The message to sign.', example: 'Hello, world!' }),
              walletSecretId: z
                .string()
                .regex(/^[a-zA-Z0-9-]{1,100}$/)
                .exactOptional()
                .openapi({
                  description:
                    'Required when not using delegated signing. The ID of the Temporary Wallet Secret that was used to sign the X-Wallet-Auth Header.',
                  example: 'e051beeb-7163-4527-a5b6-35e301529ff2',
                }),
            })
            .openapi({ required: ['address', 'message'] }),
        },
      },
    },
  },
  responses: {
    200: {
      description: 'Successfully signed message.',
      content: {
        'application/json': {
          schema: z
            .object({
              signature: z
                .string()
                .openapi({
                  description: 'The signature of the message, as a 0x-prefixed hex string.',
                  example:
                    '0x1b0c9cf8cd4554c6c6d9e7311e88f1be075d7f25b418a044f4bf2c0a42a93e212ad0a8b54de9e0b5f7e3812de3f2c6cc79aa8c3e1c02e7ad14b4a8f42012c2c01b',
                }),
            })
            .openapi({ required: ['signature'] }),
        },
      },
    },
    401: UnauthorizedErrorResponse,
    402: PaymentMethodRequiredErrorResponse,
    403: DelegationForbiddenErrorResponse,
    404: {
      description: 'Not found.',
      content: {
        'application/json': {
          schema: ErrorSchema,
          examples: {
            not_found: {
              value: {
                errorType: 'not_found',
                errorMessage: 'EVM account with the given address not found.',
              },
            },
          },
        },
      },
    },
    409: AlreadyExistsErrorResponse,
    422: IdempotencyErrorResponse,
    500: InternalServerErrorResponse,
    502: BadGatewayErrorResponse,
    503: ServiceUnavailableErrorResponse,
  },
  security: [{ endUserAuth: [] }, { apiKeyAuth: [] }],
})

