export const postV2EmbeddedWalletApiEndUsersUserIdAddressAddressDelegationRoute = createRoute({
  method: 'post',
  path: '/v2/embedded-wallet-api/end-users/{userId}/address/{address}/delegation',
  tags: ['End User Accounts'],
  summary: 'Create account-scoped delegation for end user',
  description:
    "Creates an account-scoped delegation that allows a developer to sign on behalf of an end user for a single blockchain account (identified by its address) for the specified duration. The end user must be authenticated to authorize this delegation.\nMultiple account-scoped delegations may exist concurrently for a single end user (one per canonical account address). Account-scoped and user-scoped delegations cannot coexist for the same user.\nWhen the address corresponds to an EVM Smart Account, the delegation is scoped to the Smart Account's owner EOA rather than the Smart Account address itself. This means `/address/{smartAccountAddress}/delegation` and `/address/{ownerEoaAddress}/delegation` resolve to the same delegation, and the 409 `account_scoped_delegation_active` error may be returned when creating via either address if one already exists for the canonical owner.",
  operationId: 'createDelegationForEndUserAccount',
  request: {
    headers: z.object({
      'X-Wallet-Auth': XWalletAuthParamsSchema,
      'X-Idempotency-Key': IdempotencyKeyParamsSchema,
    }),
    params: z.object({
      userId: z
        .string()
        .regex(/^[a-zA-Z0-9-]{1,100}$/)
        .openapi({
          param: {
            name: 'userId',
            in: 'path',
            required: true,
            description: 'The ID of the end user.',
            schema: {
              type: 'string',
              pattern: '^[a-zA-Z0-9-]{1,100}$',
              example: 'e051beeb-7163-4527-a5b6-35e301529ff2',
            },
          },
          example: 'e051beeb-7163-4527-a5b6-35e301529ff2',
        }),
      address: BlockchainAddressSchema.openapi({
        param: {
          name: 'address',
          in: 'path',
          required: true,
          description:
            'The blockchain address of the end user account to scope this delegation to. Format varies by network (e.g., 0x-prefixed for EVM, base58 for Solana). For EVM addresses, matching is case-insensitive.',
          schema: { $ref: '#/components/schemas/BlockchainAddress' },
          example: '0x742d35Cc6634C0532925a3b844Bc454e4438f44e',
        },
      }),
    }),
    query: z.object({ projectID: ProjectIDOptionalParamsSchema }),
    body: {
      content: {
        'application/json': {
          schema: z
            .object({
              expiresAt: z.iso
                .datetime({ offset: true })
                .openapi({
                  description: 'The date until which the delegation is valid.',
                  example: '2026-02-03T10:35:00Z',
                }),
              walletSecretId: z
                .string()
                .regex(/^[a-zA-Z0-9-]{1,100}$/)
                .openapi({
                  description:
                    'The ID of the Temporary Wallet Secret that was used to sign the X-Wallet-Auth Header.',
                  example: 'e051beeb-7163-4527-a5b6-35e301529ff2',
                }),
            })
            .openapi({ required: ['expiresAt', 'walletSecretId'] }),
          example: {
            expiresAt: '2026-02-03T10:35:00Z',
            walletSecretId: 'e051beeb-7163-4527-a5b6-35e301529ff2',
          },
        },
      },
      required: true,
    },
  },
  responses: {
    201: {
      description: 'Delegation created successfully.',
      content: {
        'application/json': {
          schema: z
            .object({
              expiresAt: z.iso
                .datetime({ offset: true })
                .openapi({
                  description: 'The date until which the delegation is valid.',
                  example: '2026-02-03T10:35:00Z',
                }),
            })
            .openapi({ required: ['expiresAt'] }),
          example: { expiresAt: '2026-02-03T10:35:00Z' },
        },
      },
    },
    400: {
      description: 'Invalid request.',
      content: {
        'application/json': {
          schema: ErrorSchema,
          examples: {
            missing_expiresAt: {
              value: {
                errorType: 'invalid_request',
                errorMessage: "Field 'expiresAt' is required.",
                errorLink: 'https://docs.cdp.coinbase.com/api-reference/v2/errors#invalid-request',
              },
            },
            invalid_expiresAt: {
              value: {
                errorType: 'invalid_request',
                errorMessage: "Field 'expiresAt' must be a valid ISO 8601 string.",
                errorLink: 'https://docs.cdp.coinbase.com/api-reference/v2/errors#invalid-request',
              },
            },
          },
        },
      },
    },
    401: UnauthorizedErrorResponse,
    402: PaymentMethodRequiredErrorResponse,
    404: {
      description: 'Account not found.',
      content: {
        'application/json': {
          schema: ErrorSchema,
          examples: {
            unknown_address: {
              value: {
                errorType: 'not_found',
                errorMessage: 'No account with the given address exists for this end user.',
                errorLink: 'https://docs.cdp.coinbase.com/api-reference/v2/errors#not-found',
              },
            },
          },
        },
      },
    },
    409: {
      description: 'Conflict with an existing delegation.',
      content: {
        'application/json': {
          schema: ErrorSchema,
          examples: {
            user_scoped_delegation_active: {
              value: {
                errorType: 'already_exists',
                errorMessage:
                  'A user-scoped delegation is already active for this user. Revoke it before creating an account-scoped delegation.',
                errorLink: 'https://docs.cdp.coinbase.com/api-reference/v2/errors#already-exists',
              },
            },
            account_scoped_delegation_active: {
              value: {
                errorType: 'already_exists',
                errorMessage: 'An account-scoped delegation is already active for this address.',
                errorLink: 'https://docs.cdp.coinbase.com/api-reference/v2/errors#already-exists',
              },
            },
          },
        },
      },
    },
    422: IdempotencyErrorResponse,
    429: {
      description: 'Rate limit exceeded.',
      content: {
        'application/json': {
          schema: ErrorSchema,
          examples: {
            rate_limit_exceeded: {
              value: {
                errorType: 'rate_limit_exceeded',
                errorMessage: 'Too many requests. Please try again later.',
                errorLink:
                  'https://docs.cdp.coinbase.com/api-reference/v2/errors#rate-limit-exceeded',
              },
            },
          },
        },
      },
    },
    500: InternalServerErrorResponse,
    502: BadGatewayErrorResponse,
    503: ServiceUnavailableErrorResponse,
  },
  security: [{ endUserAuth: [] }],
})

