export const postV2EmbeddedWalletApiEndUsersUserIdEvmSmartAccountsAddressSendRoute = createRoute({
  method: 'post',
  path: '/v2/embedded-wallet-api/end-users/{userId}/evm/smart-accounts/{address}/send',
  tags: ['End User Accounts'],
  summary: 'Send user operation for end user Smart Account',
  description: "Prepares, signs, and sends a user operation for an end user's Smart Account.",
  operationId: 'sendUserOperationWithEndUserAccount',
  request: {
    headers: z.object({
      'X-Idempotency-Key': IdempotencyKeyParamsSchema,
      'X-Wallet-Auth': XWalletAuthOptionalParamsSchema,
      'X-Developer-Auth': XDeveloperAuthParamsSchema,
    }),
    params: z.object({
      userId: z
        .string()
        .regex(/^[a-zA-Z0-9-]{1,100}$/)
        .openapi({
          param: {
            name: 'userId',
            in: 'path',
            required: true,
            description: 'The ID of the end user.',
            schema: {
              type: 'string',
              pattern: '^[a-zA-Z0-9-]{1,100}$',
              example: 'e051beeb-7163-4527-a5b6-35e301529ff2',
            },
          },
          example: 'e051beeb-7163-4527-a5b6-35e301529ff2',
        }),
      address: z
        .string()
        .regex(/^0x[0-9a-fA-F]{40}$/)
        .openapi({
          param: {
            name: 'address',
            description: 'The address of the EVM Smart Account to execute the user operation from.',
            in: 'path',
            required: true,
            schema: { type: 'string', pattern: '^0x[0-9a-fA-F]{40}$' },
            example: '0x742d35Cc6634C0532925a3b844Bc454e4438f44e',
          },
        }),
    }),
    query: z.object({ projectID: ProjectIDOptionalParamsSchema }),
    body: {
      content: {
        'application/json': {
          schema: z
            .object({
              network: EvmUserOperationNetworkSchema,
              calls: z
                .array(EvmCallSchema)
                .openapi({ description: 'The list of calls to make from the Smart Account.' }),
              useCdpPaymaster: z
                .boolean()
                .openapi({
                  description: 'Whether to use the CDP Paymaster for the user operation.',
                  example: true,
                }),
              paymasterUrl: UrlSchema.exactOptional().openapi({
                description:
                  'The URL of the paymaster to use for the user operation. If using the CDP Paymaster, use the `useCdpPaymaster` option.',
                example: 'https://api.developer.coinbase.com/rpc/v1/base/<token>',
              }),
              paymasterContext: PaymasterContextSchema.exactOptional(),
              walletSecretId: z
                .string()
                .regex(/^[a-zA-Z0-9-]{1,100}$/)
                .exactOptional()
                .openapi({
                  description:
                    'Required when not using delegated signing. The ID of the Temporary Wallet Secret that was used to sign the X-Wallet-Auth Header.',
                  example: 'e051beeb-7163-4527-a5b6-35e301529ff2',
                }),
              dataSuffix: z
                .string()
                .regex(/^0x[0-9a-fA-F]+$/)
                .exactOptional()
                .openapi({
                  description:
                    'The EIP-8021 data suffix (hex-encoded) that enables transaction attribution for the user operation.',
                  example: '0xdddddddd62617365617070070080218021802180218021802180218021',
                }),
            })
            .openapi({ required: ['network', 'calls', 'useCdpPaymaster'] }),
        },
      },
    },
  },
  responses: {
    200: {
      description: 'The user operation was successfully prepared, signed, and sent.',
      content: { 'application/json': { schema: EvmUserOperationSchema } },
    },
    400: {
      description: 'Invalid request.',
      content: {
        'application/json': {
          schema: ErrorSchema,
          examples: {
            invalid_request: {
              value: { errorType: 'invalid_request', errorMessage: 'Field "network" is required.' },
            },
            paymaster_context_without_paymaster: {
              value: {
                errorType: 'invalid_request',
                errorMessage:
                  'paymasterContext requires a paymaster: set paymasterUrl or useCdpPaymaster.',
              },
            },
            invalid_signature: {
              value: {
                errorType: 'invalid_signature',
                errorMessage: 'Failed to sign user operation.',
              },
            },
          },
        },
      },
    },
    401: UnauthorizedErrorResponse,
    402: PaymentMethodRequiredErrorResponse,
    403: DelegationForbiddenErrorResponse,
    404: {
      description: 'Not found.',
      content: {
        'application/json': {
          schema: ErrorSchema,
          examples: {
            not_found: {
              value: {
                errorType: 'not_found',
                errorMessage: 'End user Smart Account with the given address not found.',
              },
            },
          },
        },
      },
    },
    429: {
      description: 'Rate limit exceeded.',
      content: {
        'application/json': {
          schema: ErrorSchema,
          examples: {
            rate_limit_exceeded: {
              value: {
                errorType: 'rate_limit_exceeded',
                errorMessage: 'Max concurrent user operations reached.',
              },
            },
          },
        },
      },
    },
    500: InternalServerErrorResponse,
    502: BadGatewayErrorResponse,
    503: ServiceUnavailableErrorResponse,
  },
  security: [{ endUserAuth: [] }, { apiKeyAuth: [] }],
})

