      400: {
        description: 'Invalid request.',
        content: {
          'application/json': {
            schema: ErrorSchema,
            examples: {
              invalid_request: {
                value: {
                  errorType: 'invalid_request',
                  errorMessage: 'Invalid smart account address.',
                },
              },
              conflicting_paymaster: {
                value: {
                  errorType: 'invalid_request',
                  errorMessage: 'Cannot specify both useCdpPaymaster and custom paymasterUrl',
                  errorLink:
                    'https://docs.cdp.coinbase.com/embedded-wallets/evm-features/smart-accounts#gas-sponsorship-with-paymaster',
                },
              },
            },
          },
        },
      },
      401: UnauthorizedErrorResponse,
      402: PaymentMethodRequiredErrorResponse,
      404: {
        description: 'Not found.',
        content: {
          'application/json': {
            schema: ErrorSchema,
            examples: {
              borrow_position_not_found: {
                value: {
                  errorType: 'not_found',
                  errorMessage:
                    "Borrow position not found for this account on borrow product 'bp_07fb56c0-9afe-5440-8ff2-5b0e115458df'.",
                },
              },
              end_user_not_found: {
                value: { errorType: 'not_found', errorMessage: 'End user not found.' },
              },
              smart_account_not_found: {
                value: {
                  errorType: 'not_found',
                  errorMessage: 'Smart account not found for this end user.',
                },
              },
            },
          },
        },
      },
      409: {
        description:
          'Conflict. A borrow position operation for this account and product is already in progress.',
        content: {
          'application/json': {
            schema: ErrorSchema,
            examples: {
              operation_in_progress: {
                value: {
                  errorType: 'already_exists',
                  errorMessage:
                    'A borrow position operation for this account and product is already in progress. In-progress operations typically complete in under 30 seconds. Please wait for it to complete before retrying.',
                },
              },
            },
          },
        },
      },
      500: InternalServerErrorResponse,
      502: BadGatewayErrorResponse,
