export const postV2EvmAccountsRoute = createRoute({
  method: 'post',
  path: '/v2/evm/accounts',
  tags: ['EVM Accounts'],
  summary: 'Create EVM account',
  description: 'Creates a new EVM account.',
  operationId: 'createEvmAccount',
  request: {
    headers: z.object({
      'X-Wallet-Auth': XWalletAuthParamsSchema,
      'X-Idempotency-Key': IdempotencyKeyParamsSchema,
    }),
    body: {
      content: {
        'application/json': {
          schema: z
            .object({
              name: z
                .string()
                .regex(/^[A-Za-z0-9][A-Za-z0-9-]{0,34}[A-Za-z0-9]$/)
                .exactOptional()
                .openapi({
                  description:
                    "An optional name for the account.\nAccount names can consist of alphanumeric characters and hyphens, and be between 2 and 36 characters long.\nAccount names must be unique across all EVM accounts in the developer's CDP Project.",
                  example: 'my-wallet',
                }),
              accountPolicy: z
                .string()
                .regex(
                  /^[0-9a-fA-F]{8}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{12}$/,
                )
                .exactOptional()
                .openapi({
                  'x-audience': 'public',
                  description: 'The ID of the account-level policy to apply to the account.',
                  example: '123e4567-e89b-12d3-a456-426614174000',
                }),
            })
            .openapi({ required: [] }),
        },
      },
    },
  },
  responses: {
    201: {
      description: 'Successfully created EVM account.',
      content: { 'application/json': { schema: EvmAccountSchema } },
    },
    400: {
      description: 'Invalid request.',
      content: {
        'application/json': {
          schema: ErrorSchema,
          examples: {
            invalid_request: {
              value: {
                errorType: 'invalid_request',
                errorMessage: 'Project has no secret. Please register a secret with the project.',
              },
            },
          },
        },
      },
    },
    401: {
      description: 'Unauthorized.',
      content: {
        'application/json': {
          schema: ErrorSchema,
          examples: {
            unauthorized: {
              value: { errorType: 'unauthorized', errorMessage: 'Wallet authentication error.' },
            },
          },
        },
      },
    },
    402: PaymentMethodRequiredErrorResponse,
    409: {
      description: 'Resource already exists.',
      content: {
        'application/json': {
          schema: ErrorSchema,
          examples: {
            already_exists: {
              value: {
                errorType: 'already_exists',
                errorMessage: 'EVM account with the given name already exists.',
              },
            },
          },
        },
      },
    },
    422: IdempotencyErrorResponse,
    500: InternalServerErrorResponse,
    502: BadGatewayErrorResponse,
    503: ServiceUnavailableErrorResponse,
  },
  security: [{ apiKeyAuth: [] }],
})

