export const postV2EvmAccountsAddressSendTransactionRoute = createRoute({
  method: 'post',
  path: '/v2/evm/accounts/{address}/send/transaction',
  tags: ['EVM Accounts'],
  summary: 'Send transaction',
  description:
    'Signs a transaction with the given EVM account and sends it to the indicated supported network. This API handles nonce management and gas estimation, leaving the developer to provide only the minimal set of fields necessary to send the transaction. The transaction should be serialized as a hex string using [RLP](https://ethereum.org/en/developers/docs/data-structures-and-encoding/rlp/).\n\nThe transaction must be an [EIP-1559 dynamic fee transaction](https://github.com/ethereum/EIPs/blob/master/EIPS/eip-1559.md).\n\n\n**Transaction fields and API behavior**\n\n- `to` *(Required)*: The address of the contract or account to send the transaction to.\n- `chainId` *(Ignored)*: The value of the `chainId` field in the transaction is ignored.\n  The transaction will be sent to the network indicated by the `network` field in the request body.\n\n- `nonce` *(Optional)*: The nonce to use for the transaction. If not provided, the API will assign\n   a nonce to the transaction based on the current state of the account.\n\n- `maxPriorityFeePerGas` *(Optional)*: The maximum priority fee per gas to use for the transaction.\n   If not provided, the API will estimate a value based on current network conditions.\n\n- `maxFeePerGas` *(Optional)*: The maximum fee per gas to use for the transaction.\n   If not provided, the API will estimate a value based on current network conditions.\n\n- `gasLimit` *(Optional)*: The gas limit to use for the transaction. If not provided, the API will estimate a value\n  based on the `to` and `data` fields of the transaction.\n\n- `value` *(Optional)*: The amount of ETH, in wei, to send with the transaction.\n- `data` *(Optional)*: The data to send with the transaction; only used for contract calls.\n- `accessList` *(Optional)*: The access list to use for the transaction.',
  operationId: 'sendEvmTransaction',
  request: {
    headers: z.object({
      'X-Wallet-Auth': XWalletAuthParamsSchema,
      'X-Idempotency-Key': IdempotencyKeyParamsSchema,
    }),
    params: z.object({
      address: z
        .string()
        .regex(/^0x[0-9a-fA-F]{40}$/)
        .openapi({
          param: {
            name: 'address',
            description: 'The 0x-prefixed address of the Ethereum account.',
            in: 'path',
            required: true,
            schema: { type: 'string', pattern: '^0x[0-9a-fA-F]{40}$' },
            example: '0x742d35Cc6634C0532925a3b844Bc454e4438f44e',
          },
        }),
    }),
    body: {
      content: {
        'application/json': {
          schema: z
            .object({
              network: z
                .enum([
                  'base',
                  'base-sepolia',
                  'ethereum',
                  'ethereum-sepolia',
                  'avalanche',
                  'polygon',
                  'optimism',
                  'arbitrum',
                  'arbitrum-sepolia',
                  'world',
                  'world-sepolia',
                ])
                .openapi({
                  description: 'The network to send the transaction to.',
                  example: 'base-sepolia',
                }),
              transaction: z
                .string()
                .openapi({
                  description:
                    'The RLP-encoded transaction to sign and send, as a 0x-prefixed hex string.',
                  example:
                    '0xf86b098505d21dba00830334509431415daf58e2c6b7323b4c58712fd92952145da79018080',
                }),
            })
            .openapi({ required: ['transaction', 'network'] }),
        },
      },
    },
  },
  responses: {
    200: {
      description: 'Successfully signed and sent transaction.',
      content: {
        'application/json': {
          schema: z
            .object({
              transactionHash: z
                .string()
                .openapi({
                  description: 'The hash of the transaction, as a 0x-prefixed hex string.',
                  example: '0xf8f98fb6726fc936f24b2007df5cb20e2b8444ff3dfaa2a929335f432a9be2e7',
                }),
            })
            .openapi({ required: ['transactionHash'] }),
        },
      },
    },
    400: {
      description: 'Invalid request.',
      content: {
        'application/json': {
          schema: ErrorSchema,
          examples: {
            malformed_transaction: {
              value: {
                errorType: 'malformed_transaction',
                errorMessage: 'Malformed unsigned transaction.',
              },
            },
          },
        },
      },
    },
    401: {
      description: 'Unauthorized.',
      content: {
        'application/json': {
          schema: ErrorSchema,
          examples: {
            unauthorized: {
              value: { errorType: 'unauthorized', errorMessage: 'Wallet authentication error.' },
            },
          },
        },
      },
    },
    402: PaymentMethodRequiredErrorResponse,
    403: {
      description: 'Access to resource forbidden.',
      content: {
        'application/json': {
          schema: ErrorSchema,
          examples: {
            forbidden: {
              value: {
                errorType: 'forbidden',
                errorMessage: 'Unable to sign transaction for this address.',
              },
            },
          },
        },
      },
    },
    404: {
      description: 'Not found.',
      content: {
        'application/json': {
          schema: ErrorSchema,
          examples: {
            not_found: {
              value: {
                errorType: 'not_found',
                errorMessage: 'EVM account with the given address not found.',
              },
            },
          },
        },
      },
    },
    409: AlreadyExistsErrorResponse,
    422: IdempotencyErrorResponse,
    500: InternalServerErrorResponse,
    502: BadGatewayErrorResponse,
    503: ServiceUnavailableErrorResponse,
  },
  security: [{ apiKeyAuth: [] }],
})

