export const postV2EvmSmartAccountsRoute = createRoute({
  method: 'post',
  path: '/v2/evm/smart-accounts',
  tags: ['EVM Smart Accounts'],
  summary: 'Create Smart Account',
  description: 'Creates a new Smart Account.',
  operationId: 'createEvmSmartAccount',
  request: {
    headers: z.object({ 'X-Idempotency-Key': IdempotencyKeyParamsSchema }),
    body: {
      content: {
        'application/json': {
          schema: z
            .object({
              owners: z
                .array(z.string().regex(/^0x[0-9a-fA-F]{40}$/))
                .openapi({
                  description:
                    'Today, only a single owner can be set for a Smart Account, but this is an array to allow setting multiple owners in the future.',
                  example: ['0xfc807D1bE4997e5C7B33E4d8D57e60c5b0f02B1a'],
                }),
              name: z
                .string()
                .regex(/^[A-Za-z0-9][A-Za-z0-9-]{0,34}[A-Za-z0-9]$/)
                .exactOptional()
                .openapi({
                  description:
                    "An optional name for the account.\nAccount names can consist of alphanumeric characters and hyphens, and be between 2 and 36 characters long.\nAccount names must be unique across all EVM accounts in the developer's CDP Project.",
                  example: 'my-smart-wallet',
                }),
            })
            .openapi({ required: ['owners'] }),
        },
      },
    },
  },
  responses: {
    201: {
      description: 'Successfully created Smart Account.',
      content: { 'application/json': { schema: EvmSmartAccountSchema } },
    },
    400: {
      description: 'Invalid request.',
      content: {
        'application/json': {
          schema: ErrorSchema,
          examples: {
            invalid_request: {
              value: {
                errorType: 'invalid_request',
                errorMessage: 'Invalid owner address or account name provided.',
              },
            },
          },
        },
      },
    },
    402: PaymentMethodRequiredErrorResponse,
    500: InternalServerErrorResponse,
    502: BadGatewayErrorResponse,
    503: ServiceUnavailableErrorResponse,
  },
  security: [{ apiKeyAuth: [] }],
})

