export const getV2EvmSmartAccountsAddressSpendPermissionsListRoute = createRoute({
  method: 'get',
  path: '/v2/evm/smart-accounts/{address}/spend-permissions/list',
  tags: ['EVM Smart Accounts'],
  summary: 'List spend permissions',
  description: 'Lists spend permission for the given smart account address.',
  operationId: 'listSpendPermissions',
  request: {
    params: z.object({
      address: z
        .string()
        .regex(/^0x[0-9a-fA-F]{40}$/)
        .openapi({
          param: {
            name: 'address',
            description: 'The address of the Smart account to list spend permissions for.',
            in: 'path',
            required: true,
            schema: { type: 'string', pattern: '^0x[0-9a-fA-F]{40}$' },
            example: '0x742d35Cc6634C0532925a3b844Bc454e4438f44e',
          },
        }),
    }),
    query: z.object({
      pageSize: z
        .preprocess(
          (val) =>
            typeof val === 'string' &&
            /^-?(\d+(\.\d*)?|\.\d+)([eE][+-]?\d+)?$/.test(val) &&
            (!/^-?\d+$/.test(val) || Number.isSafeInteger(Number(val)))
              ? Number(val)
              : val,
          z.int(),
        )
        .default(20)
        .exactOptional()
        .openapi({
          param: {
            name: 'pageSize',
            description: 'The number of spend permissions to return per page.',
            in: 'query',
            required: false,
            schema: { type: 'integer', default: 20 },
            example: 10,
          },
        }),
      pageToken: z
        .string()
        .exactOptional()
        .openapi({
          param: {
            name: 'pageToken',
            description:
              'The token for the next page of spend permissions. Will be empty if there are no more spend permissions to fetch.',
            in: 'query',
            required: false,
            schema: { type: 'string' },
            example: 'eyJsYXN0X2lkIjogImFiYzEyMyIsICJ0aW1lc3RhbXAiOiAxNzA3ODIzNzAxfQ==',
          },
        }),
    }),
  },
  responses: {
    200: {
      description: 'Successfully listed spend permissions.',
      content: {
        'application/json': {
          schema: z
            .object({
              spendPermissions: z
                .array(SpendPermissionResponseObjectSchema)
                .openapi({ description: 'The spend permissions for the smart account.' }),
            })
            .openapi({ required: ['spendPermissions'] })
            .and(ListResponseSchema),
        },
      },
    },
    400: {
      description: 'Invalid request.',
      content: {
        'application/json': {
          schema: ErrorSchema,
          examples: {
            invalid_request: {
              value: {
                errorType: 'invalid_request',
                errorMessage: 'Invalid request. Please check the request body and parameters.',
              },
            },
          },
        },
      },
    },
    404: {
      description: 'Not found.',
      content: {
        'application/json': {
          schema: ErrorSchema,
          examples: {
            not_found: {
              value: { errorType: 'not_found', errorMessage: 'Smart account not found.' },
            },
          },
        },
      },
    },
    500: InternalServerErrorResponse,
    502: BadGatewayErrorResponse,
    503: ServiceUnavailableErrorResponse,
  },
  security: [{ apiKeyAuth: [] }],
})

