export const postV2SolanaAccountsAddressSignTransactionRoute = createRoute({
  method: 'post',
  path: '/v2/solana/accounts/{address}/sign/transaction',
  tags: ['Solana Accounts'],
  summary: 'Sign transaction',
  description:
    'Signs a transaction with the given Solana account.\nThe unsigned transaction should be serialized into a byte array and then encoded as base64.\n\n**Transaction types**\n\nThe following transaction types are supported:\n* [Legacy transactions](https://solana-labs.github.io/solana-web3.js/classes/Transaction.html)\n* [Versioned transactions](https://solana-labs.github.io/solana-web3.js/classes/VersionedTransaction.html)\n\nThe developer is responsible for ensuring that the unsigned transaction is valid, as the API will not validate the transaction.',
  operationId: 'signSolanaTransaction',
  request: {
    headers: z.object({
      'X-Wallet-Auth': XWalletAuthParamsSchema,
      'X-Idempotency-Key': IdempotencyKeyParamsSchema,
    }),
    params: z.object({
      address: z
        .string()
        .regex(/^[1-9A-HJ-NP-Za-km-z]{32,44}$/)
        .openapi({
          param: {
            name: 'address',
            description: 'The base58 encoded address of the Solana account.',
            in: 'path',
            required: true,
            schema: { type: 'string', pattern: '^[1-9A-HJ-NP-Za-km-z]{32,44}$' },
            example: 'HpabPRRCFbBKSuJr5PdkVvQc85FyxyTWkFM2obBRSvHT',
          },
        }),
    }),
    body: {
      content: {
        'application/json': {
          schema: z
            .object({
              network: z
                .enum(['solana', 'solana-devnet'])
                .exactOptional()
                .openapi({
                  description:
                    'The Solana network the transaction targets. Required when using versioned transactions that reference address lookup tables, since resolving those tables requires querying a specific network. Optional otherwise.',
                  example: 'solana-devnet',
                }),
              transaction: z
                .string()
                .openapi({
                  description: 'The base64 encoded transaction to sign.',
                  example:
                    'AQABAgIAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAQABAQECAwQFBgcICQoLDA0ODxAREhMUFRYXGBkaGxwdHh8CBgMBAQAAAAIBAwQAAAAABgIAAAAAAAYDBQEBAAAGBAgAAAAABgUAAAAA6AMAAAAAAAAGBgUBAQEBBgcEAQAAAAYICgMBAQIDBgkCBgAAAAYKAwABAQEGCwMGAQEBBgwDAAABAQAAAAA=',
                }),
            })
            .openapi({ required: ['transaction'] }),
        },
      },
    },
  },
  responses: {
    200: {
      description: 'Successfully signed transaction.',
      content: {
        'application/json': {
          schema: z
            .object({
              signedTransaction: z
                .string()
                .openapi({
                  description: 'The base64 encoded signed transaction.',
                  example:
                    '',
                }),
            })
            .openapi({ required: ['signedTransaction'] }),
        },
      },
    },
    400: {
      description: 'Invalid request.',
      content: {
        'application/json': {
          schema: ErrorSchema,
          examples: {
            malformed_transaction: {
              value: {
                errorType: 'malformed_transaction',
                errorMessage: 'Malformed unsigned transaction.',
              },
            },
            network_required_for_address_lookup_tables: {
              value: {
                errorType: 'invalid_request',
                errorMessage:
                  'network is required to sign transactions that reference address lookup tables.',
              },
            },
          },
        },
      },
    },
    401: {
      description: 'Unauthorized.',
      content: {
        'application/json': {
          schema: ErrorSchema,
          examples: {
            unauthorized: {
              value: { errorType: 'unauthorized', errorMessage: 'Wallet authentication error.' },
            },
          },
        },
      },
    },
    402: PaymentMethodRequiredErrorResponse,
    403: {
      description: 'Access to resource forbidden.',
      content: {
        'application/json': {
          schema: ErrorSchema,
          examples: {
            forbidden: {
              value: {
                errorType: 'forbidden',
                errorMessage: 'Unable to sign transaction for this address.',
              },
            },
          },
        },
      },
    },
    404: {
      description: 'Solana account not found.',
      content: {
        'application/json': {
          schema: ErrorSchema,
          examples: {
            not_found: {
              value: {
                errorType: 'not_found',
                errorMessage: 'Solana account with the given address not found.',
              },
            },
          },
        },
      },
    },
    409: AlreadyExistsErrorResponse,
    422: IdempotencyErrorResponse,
    500: InternalServerErrorResponse,
    502: BadGatewayErrorResponse,
    503: ServiceUnavailableErrorResponse,
  },
  security: [{ apiKeyAuth: [] }],
})

