export const getV2DataWebhooksSubscriptionsSubscriptionIdEventsRoute = createRoute({
  method: 'get',
  path: '/v2/data/webhooks/subscriptions/{subscriptionId}/events',
  tags: ['Webhooks'],
  summary: 'List webhook subscription events',
  description:
    'Retrieve webhook event delivery attempts for a specific subscription.\nReturns event deliveries in descending order by creation time (newest first),\nincluding delivery status, retry count, and response details.\n\n### Use Cases\n- Debug webhook delivery failures and inspect response codes\n- Monitor delivery status and retry counts\n- Audit event delivery history for a subscription\n- Verify that expected events were sent to webhook URLs\n\n### Filtering\nUse optional query parameters to narrow results:\n- `eventId` — find a specific event by ID\n- `minCreatedAt` / `maxCreatedAt` — filter by time range\n- `eventTypeNames` — filter by event type (comma-separated)\n\n**Note:** Results are limited to the 50 most recent events (newest first). No pagination is supported.\n',
  operationId: 'listWebhookSubscriptionEvents',
  request: {
    params: z.object({
      subscriptionId: z
        .uuid()
        .regex(/^[a-f0-9\-]{36}$/)
        .openapi({
          param: {
            name: 'subscriptionId',
            in: 'path',
            required: true,
            description: 'Unique identifier for the webhook subscription.',
            schema: { type: 'string', format: 'uuid', pattern: '^[a-f0-9\\-]{36}$' },
            example: '123e4567-e89b-12d3-a456-426614174000',
          },
        }),
    }),
    query: z.object({
      eventId: z
        .uuid()
        .exactOptional()
        .openapi({
          param: {
            name: 'eventId',
            in: 'query',
            required: false,
            description: 'Filter by a specific event ID.',
            schema: { type: 'string', format: 'uuid' },
            example: 'a1b2c3d4-e5f6-7890-abcd-ef1234567890',
          },
        }),
      minCreatedAt: z.iso
        .datetime({ offset: true })
        .exactOptional()
        .openapi({
          param: {
            name: 'minCreatedAt',
            in: 'query',
            required: false,
            description: 'Filter events created at or after this timestamp (RFC 3339 format).',
            schema: { type: 'string', format: 'date-time' },
            example: '2025-01-15T00:00:00Z',
          },
        }),
      maxCreatedAt: z.iso
        .datetime({ offset: true })
        .exactOptional()
        .openapi({
          param: {
            name: 'maxCreatedAt',
            in: 'query',
            required: false,
            description: 'Filter events created at or before this timestamp (RFC 3339 format).',
            schema: { type: 'string', format: 'date-time' },
            example: '2025-01-16T00:00:00Z',
          },
        }),
      eventTypeNames: z
        .string()
        .exactOptional()
        .openapi({
          param: {
            name: 'eventTypeNames',
            in: 'query',
            required: false,
            description: 'Filter by event type names (comma-separated).',
            schema: { type: 'string' },
            example: 'onchain.activity.detected',
          },
        }),
    }),
  },
  responses: {
    200: {
      description: 'Webhook events retrieved successfully.',
      content: { 'application/json': { schema: WebhookEventListResponseSchema } },
    },
    400: {
      description: 'Invalid request parameters.',
      content: {
        'application/json': {
          schema: ErrorSchema,
          examples: {
            invalid_request: {
              value: { errorType: 'invalid_request', errorMessage: 'Invalid request.' },
            },
          },
        },
      },
    },
    401: UnauthorizedErrorResponse,
    404: {
      description: 'Webhook subscription not found.',
      content: {
        'application/json': {
          schema: ErrorSchema,
          examples: {
            subscription_not_found: {
              value: {
                errorType: 'not_found',
                errorMessage:
                  'Webhook subscription not found: 123e4567-e89b-12d3-a456-426614174000',
              },
            },
          },
        },
      },
    },
    429: {
      description: 'Rate limit exceeded.',
      content: {
        'application/json': {
          schema: ErrorSchema,
          examples: {
            rate_limit_exceeded: {
              value: {
                errorType: 'rate_limit_exceeded',
                errorMessage: 'Rate limit exceeded. Please try again in a few seconds.',
              },
            },
          },
        },
      },
    },
    500: InternalServerErrorResponse,
  },
  security: [{ apiKeyAuth: [] }],
})

