export const getV2X402DiscoveryResourcesRoute = createRoute({
  method: 'get',
  path: '/v2/x402/discovery/resources',
  tags: ['x402 Facilitator'],
  summary: 'List x402 resources',
  description:
    'Lists all active discovered x402 resources.\nThis endpoint returns resources that have been discovered and cached by the x402 facilitator, including their payment requirements and metadata.\nThe response is paginated, and by default, returns 100 items per page.',
  operationId: 'listX402DiscoveryResources',
  request: {
    query: z.object({
      type: z
        .string()
        .exactOptional()
        .openapi({
          param: {
            name: 'type',
            in: 'query',
            description:
              'Filter by protocol type (e.g., "http", "mcp").\nCurrently, the only supported protocol type is "http".',
            required: false,
            schema: { type: 'string', example: 'http' },
          },
          example: 'http',
        }),
      limit: z
        .preprocess(
          (val) =>
            typeof val === 'string' &&
            /^-?(\d+(\.\d*)?|\.\d+)([eE][+-]?\d+)?$/.test(val) &&
            (!/^-?\d+$/.test(val) || Number.isSafeInteger(Number(val)))
              ? Number(val)
              : val,
          z.int(),
        )
        .default(100)
        .exactOptional()
        .openapi({
          param: {
            name: 'limit',
            in: 'query',
            description: 'The number of discovered x402 resources to return per page.',
            required: false,
            schema: { type: 'integer', default: 100 },
            example: 50,
          },
        }),
      offset: z
        .preprocess(
          (val) =>
            typeof val === 'string' &&
            /^-?(\d+(\.\d*)?|\.\d+)([eE][+-]?\d+)?$/.test(val) &&
            (!/^-?\d+$/.test(val) || Number.isSafeInteger(Number(val)))
              ? Number(val)
              : val,
          z.int(),
        )
        .default(0)
        .exactOptional()
        .openapi({
          param: {
            name: 'offset',
            in: 'query',
            description: 'The offset of the first discovered x402 resource to return.',
            required: false,
            schema: { type: 'integer', default: 0 },
            example: 0,
          },
        }),
    }),
  },
  responses: {
    200: {
      description: 'Successfully retrieved discovery list.',
      content: { 'application/json': { schema: X402DiscoveryResourcesResponseSchema } },
    },
    400: {
      description: 'Invalid request.',
      content: {
        'application/json': {
          schema: ErrorSchema,
          examples: {
            invalid_request: {
              value: {
                errorType: 'invalid_request',
                errorMessage: 'Invalid request. Please check the request parameters.',
              },
            },
          },
        },
      },
    },
    500: InternalServerErrorResponse,
    502: BadGatewayErrorResponse,
    503: ServiceUnavailableErrorResponse,
  },
  security: [{ unauthenticated: [] }],
})

