export const getV2X402DiscoverySearchRoute = createRoute({
  method: 'get',
  path: '/v2/x402/discovery/search',
  tags: ['x402 Facilitator'],
  summary: 'Search x402 resources',
  description:
    'Searches for active x402 resources using a text query and optional filters.\nSupports both text-based and vector-based search depending on availability. Results are sorted by relevance and quality score.\nLegacy network names (e.g., `base`, `base-sepolia`, `solana`) are automatically normalized to their CAIP-2 equivalents.\nThe response is limited to 20 items per request. If more results exist, `partialResults` will be `true`.',
  operationId: 'searchX402Resources',
  request: {
    query: z.object({
      query: z
        .string()
        .max(400)
        .exactOptional()
        .openapi({
          param: {
            name: 'query',
            in: 'query',
            description: 'Full-text or semantic search query to find matching resources.',
            required: false,
            schema: { type: 'string', maxLength: 400, example: 'weather forecast' },
          },
          example: 'weather forecast',
        }),
      network: z
        .string()
        .exactOptional()
        .openapi({
          param: {
            name: 'network',
            in: 'query',
            description:
              'Filter results by network in CAIP-2 format (e.g., `eip155:8453`) or legacy name (e.g., `base`, `base-sepolia`, `solana`).\nLegacy names are normalized to their CAIP-2 equivalents before filtering.',
            required: false,
            schema: { type: 'string', example: 'eip155:8453' },
          },
          example: 'eip155:8453',
        }),
      asset: z
        .string()
        .exactOptional()
        .openapi({
          param: {
            name: 'asset',
            in: 'query',
            description:
              'Filter results by asset address.\nFor EVM networks, provide a 0x-prefixed EVM address. For Solana networks, provide a base58-encoded address.\nMatching is case-insensitive.',
            required: false,
            schema: { type: 'string', example: '0x036CbD53842c5426634e7929541eC2318f3dCF7e' },
          },
          example: '0x036CbD53842c5426634e7929541eC2318f3dCF7e',
        }),
      scheme: z
        .string()
        .exactOptional()
        .openapi({
          param: {
            name: 'scheme',
            in: 'query',
            description: 'Filter results by payment scheme (e.g., `exact`).',
            required: false,
            schema: { type: 'string', example: 'exact' },
          },
          example: 'exact',
        }),
      payTo: BlockchainAddressSchema.openapi({
        param: {
          name: 'payTo',
          in: 'query',
          description:
            "Filter results by the merchant's payment address.\nFor EVM networks, provide a 0x-prefixed EVM address. For Solana networks, provide a base58-encoded address.",
          required: false,
          schema: {
            $ref: '#/components/schemas/BlockchainAddress',
            example: '0x742d35Cc6634C0532925a3b844Bc454e4438f44e',
          },
        },
      }).exactOptional(),
      urlSubstring: z
        .string()
        .min(3)
        .max(2048)
        .exactOptional()
        .openapi({
          param: {
            name: 'urlSubstring',
            in: 'query',
            description:
              'Filter results to resources whose URL contains this value (case-insensitive substring match against the resource URL).\nUseful for narrowing results to a specific domain, subdomain, or path segment. Combine with `query` to perform semantic search restricted to a URL subset.\nTip: include enough of the URL to disambiguate (e.g. `api.example.com` rather than `example`) — a short substring may also match resources whose path contains the same string.',
            required: false,
            schema: { type: 'string', minLength: 3, maxLength: 2048, example: 'api.example.com' },
          },
          example: 'api.example.com',
        }),
      maxUsdPrice: z
        .string()
        .exactOptional()
        .openapi({
          param: {
            name: 'maxUsdPrice',
            in: 'query',
            description: 'Filter results to resources with a USD price at or below this value.',
            required: false,
            schema: { type: 'string', example: '1.00' },
          },
          example: '1.00',
        }),
      extensions: z
        .preprocess(
          (val) => (val === undefined || Array.isArray(val) ? val : [val]),
          z.array(z.string()),
        )
        .exactOptional()
        .openapi({
          param: {
            name: 'extensions',
            in: 'query',
            description:
              'Filter results to resources that support the specified protocol extensions. Can be specified multiple times to filter by multiple extensions.',
            required: false,
            schema: { type: 'array', items: { type: 'string' }, example: ['bazaar'] },
            style: 'form',
            explode: true,
          },
          example: ['bazaar'],
        }),
      tags: z
        .preprocess(
          (val) => (val === undefined || Array.isArray(val) ? val : [val]),
          z.array(z.string()).max(5),
        )
        .exactOptional()
        .openapi({
          param: {
            name: 'tags',
            in: 'query',
            description:
              'Filter results to resources published with any of the specified provider tags (case-sensitive exact match). Can be specified multiple times to filter by multiple tags; a resource matches if it carries at least one of the supplied tags (OR).',
            required: false,
            schema: {
              type: 'array',
              maxItems: 5,
              items: { type: 'string' },
              example: ['weather', 'data'],
            },
            style: 'form',
            explode: true,
          },
          example: ['weather', 'data'],
        }),
      bundleSlugs: z
        .preprocess(
          (val) => (val === undefined || Array.isArray(val) ? val : [val]),
          z
            .array(
              z
                .string()
                .regex(/^[a-z0-9]+(?:-[a-z0-9]+)*$/)
                .max(64),
            )
            .max(5),
        )
        .exactOptional()
        .openapi({
          param: {
            name: 'bundleSlugs',
            in: 'query',
            description:
              'Filter results to resources that belong to any of the specified curated bundles (by bundle slug). Can be specified multiple times to filter by multiple bundles; a resource matches if it belongs to at least one of the supplied bundles (OR).',
            required: false,
            schema: {
              type: 'array',
              maxItems: 5,
              items: { type: 'string', maxLength: 64, pattern: '^[a-z0-9]+(?:-[a-z0-9]+)*$' },
              example: ['defi-trading', 'onchain-data'],
            },
            style: 'form',
            explode: true,
          },
          example: ['defi-trading', 'onchain-data'],
        }),
      curatedOnly: z
        .stringbool()
        .default(false)
        .exactOptional()
        .openapi({
          param: {
            name: 'curatedOnly',
            in: 'query',
            description:
              'When `true`, restrict results to Coinbase-curated resources (those with `curated: true`). When `false` or omitted, both curated and non-curated resources are returned.',
            required: false,
            schema: { type: 'boolean', default: false, example: true },
          },
          example: true,
        }),
      limit: z
        .preprocess(
          (val) =>
            typeof val === 'string' &&
            /^-?(\d+(\.\d*)?|\.\d+)([eE][+-]?\d+)?$/.test(val) &&
            (!/^-?\d+$/.test(val) || Number.isSafeInteger(Number(val)))
              ? Number(val)
              : val,
          z.int().min(1).max(20),
        )
        .default(20)
        .exactOptional()
        .openapi({
          param: {
            name: 'limit',
            in: 'query',
            description:
              'Maximum number of resources to return. Must be a positive integer no greater than 20.\nDefaults to 20.',
            required: false,
            schema: { type: 'integer', default: 20, maximum: 20, minimum: 1 },
            example: 20,
          },
        }),
    }),
  },
  responses: {
    200: {
      description: 'Successfully retrieved matching x402 resources.',
      content: {
        'application/json': {
          schema: X402SearchResourcesResponseSchema,
          examples: {
            search_results: {
              value: {
                x402Version: 2,
                resources: [
                  {
                    resource: 'https://api.example.com/weather/forecast',
                    description: 'Real-time weather forecast data.',
                    type: 'http',
                    x402Version: 2,
                    lastUpdated: '2024-01-15T10:30:00Z',
                    extensions: {
                      bazaar: { info: { input: { type: 'http', method: 'GET' } }, schema: {} },
                    },
                    accepts: [
                      {
                        scheme: 'exact',
                        network: 'eip155:8453',
                        amount: '1000000',
                        payTo: '0x742d35Cc6634C0532925a3b844Bc454e4438f44e',
                        asset: '0x036CbD53842c5426634e7929541eC2318f3dCF7e',
                        maxTimeoutSeconds: 60,
                      },
                    ],
                    quality: {
                      l30DaysTotalCalls: 42,
                      l30DaysUniquePayers: 15,
                      lastCalledAt: '2024-01-15T10:30:00Z',
                    },
                    curated: true,
                    skillUrl: 'https://skills.cdp.coinbase.com/weather-api/SKILL.md',
                  },
                ],
                partialResults: false,
                searchMethod: 'text',
              },
            },
          },
        },
      },
    },
    400: {
      description: 'Invalid request parameters.',
      content: {
        'application/json': {
          schema: ErrorSchema,
          examples: {
            invalid_request: {
              value: {
                errorType: 'invalid_request',
                errorMessage: 'limit must be a positive integer.',
              },
            },
          },
        },
      },
    },
    500: InternalServerErrorResponse,
    502: BadGatewayErrorResponse,
    503: ServiceUnavailableErrorResponse,
  },
  security: [{ unauthenticated: [] }],
})

