export const postV2OnrampVerificationsRoute = createRoute({
  method: 'post',
  path: '/v2/onramp/verifications',
  tags: ['Onramp'],
  summary: 'Initiate onramp verification',
  description:
    'Initiates OTP verification by sending a 6-digit code to the user via the specified channel (SMS or email). Returns a `verificationId` that must be passed to the Submit Onramp Verification endpoint along with the OTP code within 10 minutes.\n\n**Access to this API requires allowlisting.** During Onramp Headless API onboarding, contact the Onramp team to enable Onramp-managed verification for your application.',
  operationId: 'initiateOnrampVerification',
  request: {
    headers: z.object({ 'X-Idempotency-Key': IdempotencyKeyParamsSchema }),
    body: { content: { 'application/json': { schema: InitiateOnrampVerificationRequestSchema } } },
  },
  responses: {
    201: {
      description: 'Successfully initiated onramp verification.',
      content: { 'application/json': { schema: OnrampVerificationInitiationSchema } },
    },
    400: {
      description: 'Invalid request.',
      content: {
        'application/json': {
          schema: ErrorSchema,
          examples: {
            invalid_request: {
              value: {
                errorType: 'invalid_request',
                errorMessage: 'Invalid channel or destination.',
              },
            },
          },
        },
      },
    },
    401: UnauthorizedErrorResponse,
    403: ForbiddenErrorResponse,
    422: IdempotencyErrorResponse,
    429: RateLimitExceededResponse,
    500: InternalServerErrorResponse,
  },
  security: [{ apiKeyAuth: [] }],
})

export const postV2OnrampVerificationsVerificationIdSubmitRoute = createRoute({
  method: 'post',
  path: '/v2/onramp/verifications/{verificationId}/submit',
  tags: ['Onramp'],
  summary: 'Submit onramp verification',
  description:
    "Submits the OTP code to complete verification. On success, marks the verification as verified and returns the same `verificationId`. The destination does not need to be re-sent. Onramp uses the value captured at initiation time.\n\nThe returned `verificationId` should be stored on the user's device and passed to the Create Onramp Order endpoint. It is valid for 60 days.\n\n**Access to this API requires allowlisting.** During Onramp Headless API onboarding, contact the Onramp team to enable Onramp-managed verification for your application.",
  operationId: 'submitOnrampVerification',
  request: {
    params: z.object({
      verificationId: OnrampVerificationIdSchema.openapi({
        param: {
          name: 'verificationId',
          in: 'path',
          required: true,
          description: 'The verification ID returned by the Initiate Onramp Verification endpoint.',
          schema: { $ref: '#/components/schemas/OnrampVerificationId' },
          example: 'onramp_verification_a1b2c3d4-e5f6-7890-abcd-ef1234567890',
        },
      }),
    }),
    headers: z.object({ 'X-Idempotency-Key': IdempotencyKeyParamsSchema }),
    body: { content: { 'application/json': { schema: SubmitOnrampVerificationRequestSchema } } },
  },
  responses: {
    200: {
      description: 'Successfully completed onramp verification.',
      content: { 'application/json': { schema: OnrampVerificationConfirmationSchema } },
    },
    400: {
      description: 'Invalid request.',
      content: {
        'application/json': {
          schema: ErrorSchema,
          examples: {
            invalid_request: {
              value: { errorType: 'invalid_request', errorMessage: 'OTP code is required.' },
            },
            verification_code_invalid: {
              value: {
                errorType: 'otp_verification_code_invalid',
                errorMessage: 'The OTP code is incorrect or has expired.',
              },
            },
            verification_invalid: {
              value: {
                errorType: 'otp_verification_invalid',
                errorMessage:
                  'The verification record is not in a usable state for this operation.',
              },
            },
          },
        },
      },
    },
    401: UnauthorizedErrorResponse,
    403: ForbiddenErrorResponse,
    404: {
      description: 'Verification not found.',
      content: {
        'application/json': {
          schema: ErrorSchema,
          examples: {
            verification_not_found: {
              value: {
                errorType: 'otp_verification_not_found',
                errorMessage:
                  'The provided verification ID does not correspond to any verification record.',
              },
            },
          },
        },
      },
    },
    422: IdempotencyErrorResponse,
    429: RateLimitExceededResponse,
    500: InternalServerErrorResponse,
  },
  security: [{ apiKeyAuth: [] }],
})

export const postV2OnrampOrdersRoute = createRoute({
  method: 'post',
  path: '/v2/onramp/orders',
  tags: ['Onramp'],
  summary: 'Create an onramp order',
  description:
    "Create a new Onramp order or get a quote for an Onramp order. Either `paymentAmount` or `purchaseAmount` must be provided.\n\nThis API supports two modes:\n\n**Headless mode (standard)**: returns a seamless Apple Pay or Google Pay button that you integrate directly into your app. Your app collects and verifies the user's contact details before calling this endpoint — `phoneNumber`, `email`, `phoneNumberVerifiedAt`, and `agreementAcceptedAt` are required and enforced server-side.\n\n**Embedded mode**: returns a webview that collects and verifies the user's contact and identity information, then shows the payment screen. Omit both `phoneNumber` and `email` from the request to select this mode. Embedded mode requires account enablement; contact the Onramp team for access.\n\nRead more about the difference between the two modes in the [Headless Onramp overview](https://docs.cdp.coinbase.com/onramp/headless-onramp/overview).\n\nThis API supports the `GUEST_CHECKOUT_APPLE_PAY` and `GUEST_CHECKOUT_GOOGLE_PAY` payment methods.\n\nFor detailed integration instructions and to get access to this API, refer to the  [Guest Checkout Onramp API docs](https://docs.cdp.coinbase.com/onramp/headless-onramp/overview).",
  operationId: 'createOnrampOrder',
  request: {
    headers: z.object({ 'X-Onramp-Partner-Id': OnrampPartnerIdParamsSchema }),
    body: {
      content: {
        'application/json': {
          schema: z
            .object({
              agreementAcceptedAt: z.iso
                .datetime({ offset: true })
                .exactOptional()
                .openapi({
                  description:
                    'The timestamp of when the user acknowledged that by using Coinbase Onramp they are accepting the Coinbase Terms (https://www.coinbase.com/legal/guest-checkout/us), User Agreement (https://www.coinbase.com/legal/user_agreement),  and Privacy Policy (https://www.coinbase.com/legal/privacy).',
                  example: '2025-04-24T00:00:00Z',
                }),
              destinationAddress: BlockchainAddressSchema.openapi({
                description: 'The address the purchased crypto will be sent to.',
              }),
              destinationNetwork: z
                .string()
                .openapi({
                  description:
                    "The name of the crypto network the purchased currency will be sent on.\n\nUse the [Onramp Buy Options API](https://docs.cdp.coinbase.com/api-reference/rest-api/onramp-offramp/get-buy-options) to discover the supported networks for your user's location.",
                  example: 'base',
                }),
              email: z
                .string()
                .exactOptional()
                .openapi({
                  description:
                    'The verified email address of the user requesting the onramp transaction. This email must be verified by your app (via OTP) before being used with the Onramp API.',
                  example: 'test@example.com',
                }),
              isQuote: z
                .boolean()
                .default(false)
                .exactOptional()
                .openapi({
                  description:
                    'If true, this API will return a quote without creating any transaction.',
                }),
              partnerOrderRef: z
                .string()
                .exactOptional()
                .openapi({
                  description: 'Optional partner order reference ID.',
                  example: 'order-1234',
                }),
              partnerUserRef: z
                .string()
                .openapi({
                  description:
                    'A unique string that represents the user in your app. This can be used to link individual transactions together so you can retrieve the transaction history for your users. Prefix this string with "sandbox-" (e.g. "sandbox-user-1234") to perform a sandbox transaction which will allow you to test your integration without any real transfer of funds.\n\nThis value can be used with the [Onramp User Transactions API](https://docs.cdp.coinbase.com/api-reference/rest-api/onramp-offramp/get-onramp-transactions-by-id) to retrieve all transactions created by the user.',
                  example: 'user-1234',
                }),
              paymentAmount: z
                .string()
                .exactOptional()
                .openapi({
                  description:
                    'A string representing the amount of fiat the user wishes to pay in exchange for crypto. When using  this parameter, the returned quote will be inclusive of fees i.e. the user will pay this exact amount  of the payment currency.',
                  example: '100.00',
                }),
              paymentCurrency: z
                .string()
                .openapi({
                  description: 'The fiat currency to be converted to crypto.',
                  example: 'USD',
                }),
              paymentMethod: OnrampOrderPaymentMethodTypeIdSchema,
              phoneNumber: z
                .string()
                .exactOptional()
                .openapi({
                  description:
                    'The phone number of the user requesting the onramp transaction in E.164 format. This phone number must  be verified by your app (via OTP) before being used with the Onramp API.\nPlease refer to the [Onramp docs](https://docs.cdp.coinbase.com/onramp/headless-onramp/overview) for more details on phone number verification requirements and best practices.',
                  example: '+12055555555',
                }),
              phoneNumberVerifiedAt: z.iso
                .datetime({ offset: true })
                .exactOptional()
                .openapi({
                  description:
                    "Timestamp of when the user's phone number was verified via OTP. User phone number must be verified every 60 days. If this timestamp is older than 60 days, an error will be returned.",
                  example: '2025-04-24T00:00:00Z',
                }),
              smsVerificationId: OnrampVerificationIdSchema.exactOptional().openapi({
                description:
                  "The SMS verification ID returned by the Submit Onramp Verification endpoint after verifying the user's phone number. When provided, Onramp validates the server-side verification record instead of trusting `phoneNumberVerifiedAt`.",
              }),
              emailVerificationId: OnrampVerificationIdSchema.exactOptional().openapi({
                description:
                  "The email verification ID returned by the Submit Onramp Verification endpoint after verifying the user's email address.",
              }),
              purchaseAmount: z
                .string()
                .exactOptional()
                .openapi({
                  description:
                    'A string representing the amount of crypto the user wishes to purchase. When using this parameter the  returned quote will be exclusive of fees i.e. the user will receive this exact amount of the purchase  currency.',
                  example: '10.000000',
                }),
              purchaseCurrency: z
                .string()
                .openapi({
                  description:
                    "The ticker (e.g. `BTC`, `USDC`, `SOL`) or the Coinbase UUID (e.g. `d85dce9b-5b73-5c3c-8978-522ce1d1c1b4`)  of the crypto asset to be purchased.\n\nUse the [Onramp Buy Options API](https://docs.cdp.coinbase.com/api-reference/rest-api/onramp-offramp/get-buy-options) to discover the supported purchase currencies for your user's location.",
                  example: 'USDC',
                }),
              clientIp: z
                .string()
                .exactOptional()
                .openapi({
                  description: 'The IP address of the end user requesting the onramp transaction.',
                  example: '127.0.0.1',
                }),
              domain: z
                .string()
                .exactOptional()
                .openapi({
                  description:
                    'The domain that the Apple Pay or Google Pay button will be rendered on. Required when using the `GUEST_CHECKOUT_APPLE_PAY` or `GUEST_CHECKOUT_GOOGLE_PAY` payment method and embedding the payment link in an iframe. Omit this field entirely for mobile iOS Apple Pay via WebView integration.',
                  example: 'pay.coinbase.com',
                }),
              locale: z
                .string()
                .regex(/^[a-zA-Z]{2,3}(-[a-zA-Z0-9]{2,8})*$/)
                .exactOptional()
                .openapi({
                  description:
                    "Optional [BCP-47](https://www.rfc-editor.org/info/bcp47) locale tag (e.g. `es-ES`, `pt-BR`, `en`) used to localize the hosted payment page. When provided, it is appended to the returned `paymentLink` URL and mapped to the closest locale supported by the Apple Pay and Google Pay buttons; unsupported locales fall back to the user's browser language. Any well-formed BCP-47 tag is accepted.",
                  example: 'es-ES',
                }),
              userAuthToken: OnrampUserAuthTokenSchema.exactOptional().openapi({
                description:
                  'Optional. A reusable token returned by a previous verified order. When provided, a returning user checking out to the same wallet is taken straight to the pay button, skipping OTP (best-effort — an invalid, expired, or different-wallet token still requires verification).',
              }),
            })
            .openapi({
              required: [
                'paymentCurrency',
                'purchaseCurrency',
                'paymentMethod',
                'destinationAddress',
                'destinationNetwork',
                'partnerUserRef',
              ],
            }),
        },
      },
    },
  },
  responses: {
    201: {
      description: 'Successfully created an onramp order.',
      content: {
        'application/json': {
          schema: z
            .object({
              order: OnrampOrderSchema,
              paymentLink: OnrampPaymentLinkSchema.exactOptional(),
              userAuthToken: OnrampUserAuthTokenSchema.exactOptional().openapi({
                description:
                  'Present for embedded orders once the user has verified. Store this and pass it on future orders for the same user to skip OTP verification. Valid for 60 days.',
              }),
            })
            .openapi({ required: ['order'] }),
        },
      },
    },
    400: {
      description: 'Invalid request.',
      content: {
        'application/json': {
          schema: ErrorSchema,
          examples: {
            invalid_request: {
              value: { errorType: 'invalid_request', errorMessage: 'Missing required params.' },
            },
            partner_id_not_permitted: {
              value: {
                errorType: 'invalid_request',
                errorMessage:
                  'The X-Onramp-Partner-Id header is only valid for apps registered as an Onramp aggregator.',
              },
            },
            network_not_tradable: {
              value: {
                errorType: 'network_not_tradable',
                errorMessage:
                  "The selected asset cannot be purchased on the selected network in the user's location.",
              },
            },
            guest_permission_denied: {
              value: {
                errorType: 'guest_permission_denied',
                errorMessage: 'The user is not allowed to complete onramp transactions as a guest.',
              },
            },
            guest_region_forbidden: {
              value: {
                errorType: 'guest_region_forbidden',
                errorMessage: "Guest onramp transactions are not allowed in the user's region.",
              },
            },
            phone_number_verification_expired: {
              value: {
                errorType: 'phone_number_verification_expired',
                errorMessage:
                  "The user's phone number verification has expired. Please re-verify the user's phone number.",
              },
            },
            verification_expired: {
              value: {
                errorType: 'otp_verification_expired',
                errorMessage:
                  'The verification record has expired. Initiate a new verification flow.',
              },
            },
            verification_invalid: {
              value: {
                errorType: 'otp_verification_invalid',
                errorMessage:
                  'The verification record is not in a valid state for order placement.',
              },
            },
            verification_required: {
              value: {
                errorType: 'otp_verification_required',
                errorMessage:
                  "Verification is required for this application. Use the Onramp Verification API to verify the user's phone number and email.",
              },
            },
            verification_destination_mismatch: {
              value: {
                errorType: 'otp_verification_destination_mismatch',
                errorMessage:
                  'The destination on the order does not match the destination that was verified.',
              },
            },
          },
        },
      },
    },
    401: UnauthorizedErrorResponse,
    404: {
      description: 'Verification or partner not found.',
      content: {
        'application/json': {
          schema: ErrorSchema,
          examples: {
            verification_not_found: {
              value: {
                errorType: 'otp_verification_not_found',
                errorMessage:
                  'The provided verification ID does not correspond to any verification record.',
              },
            },
            partner_not_found: {
              value: {
                errorType: 'not_found',
                errorMessage:
                  'The partner identified by the X-Onramp-Partner-Id header is blocked or does not belong to this app.',
              },
            },
          },
        },
      },
    },
    429: {
      description: 'Rate limit or guest transaction quota exceeded.',
      content: {
        'application/json': {
          schema: ErrorSchema,
          examples: {
            rate_limit_exceeded: {
              value: { errorType: 'rate_limit_exceeded', errorMessage: 'Rate limit exceeded.' },
            },
            guest_transaction_limit: {
              value: {
                errorType: 'guest_transaction_limit',
                errorMessage:
                  "This transaction would exceed the user's weekly guest onramp transaction limit.",
              },
            },
            guest_transaction_count: {
              value: {
                errorType: 'guest_transaction_count',
                errorMessage:
                  'The user has reached the lifetime guest onramp transaction count limit (15).',
              },
            },
          },
        },
      },
    },
    500: InternalServerErrorResponse,
  },
  security: [{ apiKeyAuth: [] }],
})

export const getV2OnrampOrdersOrderIdRoute = createRoute({
  method: 'get',
  path: '/v2/onramp/orders/{orderId}',
  tags: ['Onramp'],
  summary: 'Get an onramp order by ID',
  description: 'Get an onramp order by ID.',
  operationId: 'getOnrampOrderById',
  request: {
    params: z.object({
      orderId: z
        .string()
        .regex(/^[a-f0-9\-]{36}$/)
        .openapi({
          param: {
            name: 'orderId',
            in: 'path',
            required: true,
            description: 'The ID of the onramp order to retrieve.',
            schema: { type: 'string', pattern: '^[a-f0-9\\-]{36}$' },
            example: '123e4567-e89b-12d3-a456-426614174000',
          },
        }),
    }),
  },
  responses: {
    200: {
      description: 'Successfully retrieved an onramp order.',
      content: {
        'application/json': {
          schema: z.object({ order: OnrampOrderSchema }).openapi({ required: ['order'] }),
        },
      },
    },
    401: UnauthorizedErrorResponse,
    404: {
      description: 'Order not found.',
      content: {
        'application/json': {
          schema: ErrorSchema,
          examples: {
            not_found: {
              value: {
                errorType: 'not_found',
                errorMessage: 'Order with the given ID does not exist.',
              },
            },
          },
        },
      },
    },
    429: RateLimitExceededResponse,
  },
  security: [{ apiKeyAuth: [] }],
})

export const postV2OnrampSessionsRoute = createRoute({
  method: 'post',
  path: '/v2/onramp/sessions',
  tags: ['Onramp'],
  summary: 'Create an onramp session',
  description:
    'Returns a single-use URL for an Onramp session. This API provides flexible  functionality based on the parameters provided, supporting three cases:\n\n**Important**: The returned URL is single-use only. Once a user visits the URL,  no one else can access it.\n## Use Cases\n### 1. Basic Session (Minimum Parameters)\n**Required**: `destinationAddress`, `purchaseCurrency`, `destinationNetwork`\n\n**Returns**: Basic single-use onramp URL. The `quote` object will not be included in the response.\n### 2. One-Click Onramp URL\n**Required**: Basic parameters + (`paymentAmount` OR `purchaseAmount`), `paymentCurrency`\n\n**Returns**: One-click onramp URL for streamlined checkout. The `quote` object will not be included in the response.\n### 3. One-Click Onramp URL with Quote\n**Required**: One-Click Onramp parameters + `paymentMethod`, `country`, `subdivision`\n\n**Returns**: Complete pricing quote and one-click onramp URL. Both `session` and `quote` objects will be included in the response.\n\n**Note**: Only one of `paymentAmount` or `purchaseAmount` should be provided, not both. Providing both will result in an error. When `paymentAmount` is provided, the quote shows how much crypto the user will receive for the specified fiat amount (fee-inclusive). When `purchaseAmount` is provided, the quote shows how much fiat the user needs to pay for the specified crypto amount (fee-exclusive).',
  operationId: 'createOnrampSession',
  request: {
    headers: z.object({ 'X-Onramp-Partner-Id': OnrampPartnerIdParamsSchema }),
    body: { content: { 'application/json': { schema: OnrampSessionRequestSchema } } },
  },
  responses: {
    201: {
      description: 'Onramp session created successfully.',
      content: {
        'application/json': {
          schema: z
            .object({ session: OnrampSessionSchema, quote: OnrampQuoteSchema.exactOptional() })
            .openapi({ required: ['session'] }),
        },
      },
    },
    400: {
      description: 'Invalid request.',
      content: {
        'application/json': {
          schema: ErrorSchema,
          examples: {
            invalid_request: {
              value: { errorType: 'invalid_request', errorMessage: 'Missing required parameters.' },
            },
            invalid_destination_address: {
              value: {
                errorType: 'invalid_request',
                errorMessage: 'The destination address is not valid for the specified network.',
              },
            },
            partner_id_not_permitted: {
              value: {
                errorType: 'invalid_request',
                errorMessage:
                  'The X-Onramp-Partner-Id header is only valid for apps registered as an Onramp aggregator.',
              },
            },
          },
        },
      },
    },
    401: UnauthorizedErrorResponse,
    404: {
      description: 'Partner not found.',
      content: {
        'application/json': {
          schema: ErrorSchema,
          examples: {
            partner_not_found: {
              value: {
                errorType: 'not_found',
                errorMessage:
                  'The partner identified by the X-Onramp-Partner-Id header is blocked or does not belong to this app.',
              },
            },
          },
        },
      },
    },
    429: RateLimitExceededResponse,
    500: InternalServerErrorResponse,
  },
  security: [{ apiKeyAuth: [] }],
})

export const postV2OnrampMobileSessionsChallengesRoute = createRoute({
  method: 'post',
  path: '/v2/onramp/mobile/sessions/challenges',
  tags: ['Onramp (App2App)'],
  summary: 'Create an onramp mobile challenge',
  description:
    'Issues a challenge for initiating an onramp flow from a partner mobile app. Authenticate this request from the partner backend with a CDP API key; do not embed the API key in the mobile client. The project is identified by the API key JWT.\n\nPass the challenge to the mobile app. The app signs it using platform attestation (iOS App Attest or Android Play Integrity) and submits it to the [Create Onramp Mobile Session](#operation/createOnrampMobileSession) endpoint without CDP API key authentication to obtain a ready-to-use onramp URL. The `redirectUrl` is required so the Coinbase app knows where to return the user after completing or dismissing the transaction.',
  operationId: 'createOnrampMobileChallenge',
  request: {
    body: {
      content: {
        'application/json': {
          schema: OnrampSessionRequestSchema.and(
            z.object({}).openapi({ required: ['redirectUrl'] }),
          ),
        },
      },
      required: true,
    },
  },
  responses: {
    201: {
      description: 'Onramp mobile challenge created successfully.',
      content: { 'application/json': { schema: OnrampMobileChallengeSchema } },
    },
    400: {
      description: 'Invalid request.',
      content: {
        'application/json': {
          schema: ErrorSchema,
          examples: {
            invalid_request: {
              value: { errorType: 'invalid_request', errorMessage: 'Missing required parameters.' },
            },
            invalid_destination_address: {
              value: {
                errorType: 'invalid_request',
                errorMessage: 'The destination address is not valid for the specified network.',
              },
            },
          },
        },
      },
    },
    401: UnauthorizedErrorResponse,
    403: {
      description: 'App not permitted to initiate a mobile handoff.',
      content: {
        'application/json': {
          schema: ErrorSchema,
          examples: {
            app_not_allowed: {
              value: {
                errorType: 'forbidden',
                errorMessage: 'App is not enabled for mobile deep-linking.',
              },
            },
          },
        },
      },
    },
    429: RateLimitExceededResponse,
    500: InternalServerErrorResponse,
    503: ServiceUnavailableErrorResponse,
  },
  security: [{ apiKeyAuth: [] }],
})

export const postV2OnrampMobileSessionsRoute = createRoute({
  method: 'post',
  path: '/v2/onramp/mobile/sessions',
  tags: ['Onramp (App2App)'],
  summary: 'Create an onramp mobile session',
  description:
    'Verifies the platform attestation for a challenge issued by [Create Onramp Mobile Challenge](#operation/createOnrampMobileChallenge) and returns a ready-to-use onramp URL. The URL embeds the session token as a query parameter so the Coinbase app can populate the handoff screen immediately on launch.\n\nThis endpoint is idempotent on the challenge token: if the same challenge is submitted again (e.g. due to a lost response), the server returns the original session URL rather than an error.\n\nProvide exactly one platform payload: `ios` (App Attest assertion) or `android` (Play Integrity token).',
  operationId: 'createOnrampMobileSession',
  request: {
    body: {
      content: { 'application/json': { schema: CreateOnrampMobileSessionRequestSchema } },
      required: true,
    },
  },
  responses: {
    201: {
      description: 'Onramp mobile session created successfully.',
      content: {
        'application/json': {
          schema: z.object({ session: OnrampSessionSchema }).openapi({ required: ['session'] }),
        },
      },
    },
    400: {
      description: 'Invalid request.',
      content: {
        'application/json': {
          schema: ErrorSchema,
          examples: {
            invalid_challenge: {
              value: {
                errorType: 'invalid_request',
                errorMessage: 'The provided challenge is invalid or has expired.',
              },
            },
            invalid_signature: {
              value: {
                errorType: 'invalid_request',
                errorMessage: 'The attestation signature could not be verified.',
              },
            },
          },
        },
      },
    },
    403: {
      description: 'App not permitted to initiate a mobile handoff.',
      content: {
        'application/json': {
          schema: ErrorSchema,
          examples: {
            app_not_allowed: {
              value: {
                errorType: 'forbidden',
                errorMessage: 'App is not enabled for mobile deep-linking.',
              },
            },
          },
        },
      },
    },
    422: {
      description: 'Attestation is stale or too old.',
      content: {
        'application/json': {
          schema: ErrorSchema,
          examples: {
            stale_attestation: {
              value: {
                errorType: 'stale_attestation',
                errorMessage:
                  'Attestation is too old. Please generate a fresh challenge and re-attest.',
              },
            },
          },
        },
      },
    },
    429: RateLimitExceededResponse,
    500: InternalServerErrorResponse,
    503: ServiceUnavailableErrorResponse,
  },
  security: [{ unauthenticated: [] }],
})

export const postV2OnrampMobileAttestationChallengesRoute = createRoute({
  method: 'post',
  path: '/v2/onramp/mobile/attestation/challenges',
  tags: ['Onramp (App2App)'],
  summary: 'Create an onramp iOS attestation challenge',
  description:
    'Issues a one-time challenge for the iOS App Attest device-key **registration** step. Authenticate with a CDP API key. Call this from the partner backend and pass the challenge to the mobile app; do not embed the API key in the client. The project is identified by the API key JWT. The partner app then passes the challenge to `DCAppAttestService.attestKey(keyId, clientDataHash: SHA256(challenge))` and submits the resulting attestation to [Register Onramp iOS Attestation](#operation/registerOnrampIosAttestation).\n\nThis is distinct from [Create Onramp Mobile Challenge](#operation/createOnrampMobileChallenge), which issues the per-transaction session challenge. Registration is a one-time, per-device-install operation; iOS-only (Android validates Play Integrity inline per request and has no registration step).',
  operationId: 'createOnrampIosAttestationChallenge',
  responses: {
    201: {
      description: 'Attestation challenge created successfully.',
      content: { 'application/json': { schema: IosAttestationChallengeSchema } },
    },
    401: UnauthorizedErrorResponse,
    403: ForbiddenErrorResponse,
    429: RateLimitExceededResponse,
    500: InternalServerErrorResponse,
  },
  security: [{ apiKeyAuth: [] }],
})

export const postV2OnrampMobileAttestationRegistrationsRoute = createRoute({
  method: 'post',
  path: '/v2/onramp/mobile/attestation/registrations',
  tags: ['Onramp (App2App)'],
  summary: 'Register a device key for iOS App Attest',
  description:
    "Verifies an iOS App Attest attestation payload and registers the device's public key for future assertion validation. The server checks that the attestation is genuine and signed by Apple, that the bundle ID is in the partner's allowed mobile clients list, and that the challenge issued by [Create Onramp iOS Attestation Challenge](#operation/createOnrampIosAttestationChallenge) is fresh and unused.\n\nThis is a one-time, per-device-install operation; iOS-only (Android validates Play Integrity inline per request and has no registration step). For security, all client-side verification failures are returned as an opaque `400 invalid_request` — the response never reveals which specific check failed.\n\nThe Apple App Attest `keyId` is supplied only in the request body (`ios.keyId`). Do not put `keyId` in the URL — App Attest key IDs are standard base64 and frequently contain `/`, which breaks path routing at the edge.\n\nIdempotency is provided by `ios.keyId` itself: the server upserts the device public key on `(app, keyId)`, so repeating registration for the same key replaces the stored public key rather than creating a duplicate. This endpoint does not accept `X-Idempotency-Key` — `ios.keyId` is the natural idempotency key for the registration resource. The challenge remains single-use and is claimed on first receipt. The challenge identifies the project; the device does not supply a CDP project ID.",
  operationId: 'registerOnrampIosAttestation',
  request: {
    body: {
      content: {
        'application/json': {
          schema: IosAttestationRegistrationRequestSchema,
          examples: {
            ios_example: {
              summary: 'iOS App Attest registration',
              value: {
                challenge: 'YWJjZGVmZ2hpamtsbW5vcHFyc3R1dnd4eXoxMjM0NTY=',
                ios: {
                  keyId: 'abc123def456',
                  attestation: 'b2F1dGhEYXRhQUFDSmdhVWRpY0FBQ1VqZw==',
                  bundleId: 'com.coinbase.cdp-onramp',
                },
              },
            },
          },
        },
      },
      required: true,
    },
  },
  responses: {
    200: {
      description:
        'Attestation verified successfully. Device public key registered for assertion validation.',
      content: { 'application/json': { schema: IosAttestationRegistrationResponseSchema } },
    },
    400: {
      description:
        'Invalid request, or the attestation could not be verified. All client-side rejections (unknown bundle ID, bad certificate chain, consumed or expired challenge, unregistered client) collapse into this single opaque error so no detail about the failed check is leaked.',
      content: {
        'application/json': {
          schema: ErrorSchema,
          examples: {
            invalid_request: {
              value: {
                errorType: 'invalid_request',
                errorMessage: 'ios attestation payload is required.',
              },
            },
            verification_failed: {
              value: {
                errorType: 'invalid_request',
                errorMessage: 'The attestation could not be verified.',
              },
            },
          },
        },
      },
    },
    429: RateLimitExceededResponse,
    500: InternalServerErrorResponse,
  },
  security: [{ unauthenticated: [] }],
})

export const postV2OnrampLimitsRoute = createRoute({
  method: 'post',
  path: '/v2/onramp/limits',
  tags: ['Onramp'],
  summary: 'Get onramp user limits',
  description:
    'Returns the transaction limits for an onramp user based on their payment method and user identifier. Use this API to show users their remaining purchase capacity before initiating an onramp transaction.\nCurrently supports `GUEST_CHECKOUT_APPLE_PAY` payment method with phone number identification. The phone number must have been previously verified via OTP.',
  operationId: 'getOnrampUserLimits',
  request: {
    body: {
      content: {
        'application/json': {
          schema: z
            .object({
              paymentMethodType: OnrampOrderPaymentMethodTypeIdSchema,
              userId: z
                .string()
                .openapi({
                  description:
                    'The user identifier value. For `phone_number` type, this must be in E.164 format.',
                  example: '+12055555555',
                }),
              userIdType: OnrampUserIdTypeSchema,
            })
            .openapi({ required: ['paymentMethodType', 'userId', 'userIdType'] }),
        },
      },
    },
  },
  responses: {
    200: {
      description: 'Successfully retrieved user limits.',
      content: {
        'application/json': {
          schema: z
            .object({
              limits: z
                .array(OnrampUserLimitSchema)
                .openapi({ description: 'The list of limits applicable to the user.' }),
              limitUpgradeOptions: z
                .array(OnrampLimitUpgradeOptionSchema)
                .exactOptional()
                .openapi({
                  description:
                    "The user's limit upgrade status and associated upgrade details. Omitted when limit upgrades are not available for the calling app or user. Use the [Request Limit Upgrade](https://docs.cdp.coinbase.com/api-reference/v2/rest-api/onramp/request-limits-upgrade) endpoint to request a limit upgrade.",
                }),
            })
            .openapi({ required: ['limits'] }),
          examples: {
            default: {
              value: {
                limits: [
                  { limitType: 'weekly_spending', currency: 'USD', limit: '500', remaining: '400' },
                  { limitType: 'lifetime_transactions', limit: '15', remaining: '12' },
                ],
                limitUpgradeOptions: [
                  {
                    status: 'unrequested',
                    fields: ['ssnLast4', 'dateOfBirth'],
                    limitUpgrades: [
                      { limitType: 'weekly_spending', maxUpgrade: '2500' },
                      { limitType: 'lifetime_transactions', maxUpgrade: '2147483647' },
                    ],
                  },
                ],
              },
            },
            active: {
              value: {
                limits: [
                  {
                    limitType: 'weekly_spending',
                    currency: 'USD',
                    limit: '2500',
                    remaining: '2000',
                  },
                  {
                    limitType: 'lifetime_transactions',
                    limit: '2147483647',
                    remaining: '2147483647',
                  },
                ],
                limitUpgradeOptions: [{ status: 'active', fields: [], limitUpgrades: [] }],
              },
            },
          },
        },
      },
    },
    400: {
      description: 'Invalid request.',
      content: {
        'application/json': {
          schema: ErrorSchema,
          examples: {
            invalid_request: {
              value: {
                errorType: 'invalid_request',
                errorMessage: 'Must provide a valid payment method type and user identifier.',
              },
            },
          },
        },
      },
    },
    401: UnauthorizedErrorResponse,
    429: RateLimitExceededResponse,
    500: InternalServerErrorResponse,
  },
  security: [{ apiKeyAuth: [] }],
})

export const postV2OnrampLimitsUpgradeRoute = createRoute({
  method: 'post',
  path: '/v2/onramp/limits/upgrade',
  tags: ['Onramp'],
  summary: 'Request limit upgrade',
  description:
    'Requests a limit upgrade for an onramp user. Only phone number is currently supported as a userId.\n\nThe default API mode submits identity information directly and returns HTTP 202 when the request is accepted. Embedded mode (`interactionMode: embedded`) returns a Coinbase-hosted `upgradeUrl` where the user enters identity information.\n\nThe verification process is asynchronous. After calling this endpoint, use the [Get Onramp User Limits](https://docs.cdp.coinbase.com/api-reference/v2/rest-api/onramp/get-onramp-user-limits) endpoint to check the status in the `limitUpgradeOptions` array.\n\n**Prerequisites:**\n- The phone number must have been previously verified by your app via OTP. - Upgrades may not be available until a certain number of successful transactions by the user.\n\n**Supported fields:**\n- `ssnLast4`: Last 4 digits of the Social Security Number (no dashes or spaces).\n- `dateOfBirth`: Date of birth (day, month, year as zero-padded strings).',
  operationId: 'requestLimitsUpgrade',
  request: {
    body: {
      content: {
        'application/json': {
          schema: OnrampLimitUpgradeRequestSchema,
          example: {
            userId: '+12055555555',
            userIdType: 'phone_number',
            fields: { ssnLast4: '5678', dateOfBirth: { day: '15', month: '08', year: '1990' } },
          },
        },
      },
    },
  },
  responses: {
    200: {
      description: 'Embedded limit upgrade URL created.',
      content: { 'application/json': { schema: OnrampLimitUpgradeEmbeddedResponseSchema } },
    },
    202: { description: 'Limit upgrade request accepted.' },
    400: {
      description: 'Invalid request.',
      content: {
        'application/json': {
          schema: ErrorSchema,
          examples: {
            invalid_request: {
              value: {
                errorType: 'invalid_request',
                errorMessage: 'Invalid user identifier or fields.',
              },
            },
          },
        },
      },
    },
    401: UnauthorizedErrorResponse,
    429: RateLimitExceededResponse,
    500: InternalServerErrorResponse,
  },
  security: [{ apiKeyAuth: [] }],
})

